-- =============================================================================
-- 431 — LE CAHIER D'EXERCICES DE 3E (partie 1)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/3e/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 431 --niveau 3e --matieres francais --suffixe 1 > supabase/contenu/431_exercices_3e_1.sql
--
-- 54 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   francais.k009           27 exercices · 9 chapitres
--   francais.k010           27 exercices · 9 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('c60e9ca7-e9f0-5615-ad66-ec1a290acd6a'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Un matin de 1915","competence":"analyser-texte","situation":"Un soldat raconte une matinée dans les tranchées. L’auteur a choisi ses mots avec soin : regarde ce qu’il met côte à côte.","documents":[{"id":"matin","type":"texte","genre":"recit","titre":"Un matin au front","blocs":["Ce matin-là, le ciel était bleu, les coquelicots bordaient le chemin et une alouette chantait au-dessus des blés.","Dans le fossé, le sergent Lambert ne bougeait plus. Une odeur de poudre et de sang montait des tranchées, et l’on entendait un blessé appeler sa mère."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche les **trois mots** de la nature paisible (une couleur, une fleur, un oiseau).","aide":"Cherche dans le premier paragraphe.","type":"zone","document":"matin","multiple":true},{"enonce":"Touche les **trois mots** qui disent la guerre (une odeur, un liquide, une personne).","aide":"Cherche dans le second paragraphe.","type":"zone","document":"matin","multiple":true},{"enonce":"Pourquoi l’auteur place-t-il ces deux univers l’un à côté de l’autre ?","aide":"Que ressent-on quand un malheur arrive par un beau temps ?","type":"choix","options":[{"id":"a","texte":"Pour rendre l’horreur plus choquante en la posant dans un décor paisible"},{"id":"b","texte":"Pour allonger le texte avec des descriptions sans rapport avec le récit"},{"id":"c","texte":"Pour montrer que la nature est cruelle et qu’elle se venge des soldats"},{"id":"d","texte":"Pour faire oublier la guerre au lecteur en décrivant surtout la nature"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m5","m7","m13"]},"explication":"Les mots de la nature paisible sont **bleu, coquelicots, alouette**."},{"cle":{"type":"zone","ids":["m30","m33","m42"]},"explication":"Les mots de la guerre sont **poudre, sang, blessé**."},{"cle":{"type":"choix","ids":["a"]},"explication":"Le décor paisible fait **ressortir l’horreur** : c’est le contraste qui rend la guerre plus insupportable."}]$ex$::jsonb),
  ('c60e9ca7-e9f0-5615-ad66-ec1a290acd6a'::uuid, 2, 2, 10, 35, 3,
   $ex${"titre":"La bataille de Bellépée","competence":"analyser-texte","situation":"Voici un petit conte écrit pour l’exercice, à la manière des contes philosophiques. Le narrateur a l’air de tout approuver… mais que pense-t-il vraiment ?","documents":[{"id":"conte","type":"texte","genre":"recit","titre":"Le royaume de Bellépée","blocs":["Le royaume de Bellépée était en fête : le roi venait de déclarer la guerre à son voisin, et l’on trouvait cela charmant.","La bataille eut lieu un mardi. Elle fut magnifique : en deux heures, dix mille hommes furent fauchés par les canons, et le roi, installé sur la colline avec sa longue-vue, déclara que tout s’était passé fort convenablement.","On chanta un Te Deum dans les deux camps, et chacun remercia le ciel de ce résultat."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche les **deux adjectifs** qui louent ce que l’auteur condamne.","aide":"Quels adjectifs flatteurs décrivent la guerre et la bataille ?","type":"zone","document":"conte","multiple":true},{"enonce":"Relie chaque procédé à son effet.","aide":"Relis ton cours : un procédé, un effet.","type":"association","gauche":[{"id":"g0","texte":"L’ironie"},{"id":"g1","texte":"L’hyperbole et l’accumulation"},{"id":"g2","texte":"Le registre pathétique"},{"id":"g3","texte":"Le registre polémique"}],"droite":[{"id":"d0","texte":"Il accuse directement"},{"id":"d1","texte":"Elles accablent par des détails insoutenables"},{"id":"d2","texte":"Elle feint d’admirer ce qu’elle condamne"},{"id":"d3","texte":"Il provoque la pitié"}]},{"enonce":"Que pense réellement le narrateur de cette bataille ?","aide":"Regarde ce que devient le sort des soldats, derrière les mots flatteurs.","type":"choix","options":[{"id":"a","texte":"C’est un mal malheureusement nécessaire"},{"id":"b","texte":"C’est un grand succès militaire"},{"id":"c","texte":"C’est un divertissement sans importance"},{"id":"d","texte":"C’est un massacre absurde"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m22","m31"]},"explication":"Les adjectifs **charmant** et **magnifique** louent ce que le narrateur condamne : c’est l’ironie."},{"cle":{"type":"association","paires":{"g3":"d0","g1":"d1","g0":"d2","g2":"d3"}},"explication":"Chaque procédé a son effet : l’ironie feint d’admirer, l’accumulation accable, le pathétique émeut, le polémique accuse."},{"cle":{"type":"choix","ids":["d"]},"explication":"Sous les compliments, le narrateur montre **un massacre absurde** : dix mille morts en deux heures, pour un roi qui s’en félicite."}]$ex$::jsonb),
  ('c60e9ca7-e9f0-5615-ad66-ec1a290acd6a'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Une exposition « Plus jamais ça »","competence":"analyser-document","situation":"Le CDI prépare une exposition sur l’art et la guerre. Voici l’affiche de l’exposition et la lettre d’un soldat, écrite pour l’occasion.","documents":[{"id":"affiche","type":"fiche","modele":"affiche","entete":"Plus jamais ça","sousTitre":"L’art face à la guerre","emoji":"🖼️","teinte":"violet","lignes":[{"texte":"Goya","valeur":"Les Désastres de la guerre (gravures)","id":"z1"},{"texte":"Picasso","valeur":"Guernica (tableau)","id":"z2"},{"texte":"Barbusse","valeur":"Le Feu (roman)","id":"z3"},{"texte":"Genevoix","valeur":"Ceux de 14 (récit)","id":"z4"}],"pied":"Salle du CDI — entrée libre"},{"id":"lettre","type":"texte","genre":"lettre","titre":"Lettre d’un soldat","blocs":["Chère Louise,","Hier, Fernand est tombé à côté de moi. Dans sa poche, son harmonica était encore tiède. La tranchée sent le moisi et la fumée, Louise, et je n’arrive plus à m’en défaire.","Vous dites à l’arrière que nous sommes des héros. Dites plutôt que nous avons peur, et que personne n’a le droit d’oublier nos noms."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Sur l’affiche, touche les **deux œuvres** qui sont des textes (et non des images).","aide":"Une gravure et un tableau sont des images. Que reste-t-il ?","type":"zone","document":"affiche","multiple":true},{"enonce":"Dans la lettre, touche **les trois détails vrais** : un prénom, un objet et une odeur.","aide":"Cherche un prénom, un objet de poche, puis ce que sent la tranchée.","type":"zone","document":"lettre","multiple":true},{"enonce":"Range chaque action : l’art peut-il la faire, ou non ?","aide":"Une œuvre n’a pas de pouvoir militaire, mais elle a une mémoire.","type":"categories","categories":[{"id":"c0","texte":"L’art peut"},{"id":"c1","texte":"L’art ne peut pas"}],"items":[{"id":"i0","texte":"Arrêter une guerre"},{"id":"i1","texte":"Désigner les responsables"},{"id":"i2","texte":"Faire signer la paix"},{"id":"i3","texte":"Rendre une voix aux victimes"},{"id":"i4","texte":"Empêcher l’oubli"}]},{"enonce":"Pourquoi Fernand, l’harmonica et le moisi sont-ils plus forts qu’un mot comme « la guerre » ?","aide":"Qu’est-ce qui reste le mieux en mémoire : une idée générale ou un prénom ?","type":"choix","options":[{"id":"a","texte":"Parce que ces mots sont plus rares"},{"id":"b","texte":"Parce que l’auteur a inventé ces détails"},{"id":"c","texte":"Parce qu’un détail vrai pèse plus lourd qu’une abstraction"},{"id":"d","texte":"Parce que la lettre est plus courte qu’un roman"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3","z4"]},"explication":"**Le Feu** et **Ceux de 14** sont des textes ; Goya et Picasso ont travaillé avec des images."},{"cle":{"type":"zone","ids":["m3","m14","m22"]},"explication":"Le prénom **Fernand**, l’objet **harmonica** et l’odeur de **moisi** : ces détails vrais pèsent plus lourd qu’une abstraction."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c1","i3":"c0","i4":"c0"}},"explication":"L’art **ne peut pas** arrêter une guerre ni signer la paix ; il **peut** empêcher l’oubli, désigner les responsables et rendre une voix aux victimes."},{"cle":{"type":"choix","ids":["c"]},"explication":"Un **détail vrai** donne un visage à la guerre : c’est ce qui fait la force du témoin."}]$ex$::jsonb),
  ('892c15e7-cd53-5fc4-b69f-2c9159171431'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"L’affiche de Valmont","competence":"analyser-texte","situation":"Une affiche clandestine circule dans la ville de Valmont. Elle est écrite pour l’exercice, mais elle emploie de vrais procédés d’écrivain engagé.","documents":[{"id":"affiche","type":"texte","genre":"article","titre":"Affiche clandestine","blocs":["Habitants de Valmont, vous qui ne dites rien, ouvrez les yeux.","On a fermé l’école. On a fermé le marché. On a fermé la bouche de ceux qui parlaient.","Combien de temps laisserons-nous faire ?","Je n’ai pas peur de signer ce texte, et nous serons bientôt mille à le signer."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui nomme **ceux à qui l’auteur s’adresse** (l’apostrophe).","aide":"Le premier mot de l’affiche interpelle quelqu’un.","type":"zone","document":"affiche","multiple":false},{"enonce":"Range chaque passage de l’affiche selon le procédé qu’il emploie.","aide":"L’anaphore répète le même début de phrase.","type":"categories","categories":[{"id":"c0","texte":"Apostrophe"},{"id":"c1","texte":"Anaphore"},{"id":"c2","texte":"Question rhétorique"},{"id":"c3","texte":"Alternance je / nous"}],"items":[{"id":"i0","texte":"On a fermé l’école. On a fermé le marché."},{"id":"i1","texte":"Combien de temps laisserons-nous faire ?"},{"id":"i2","texte":"Je n’ai pas peur… nous serons bientôt mille"},{"id":"i3","texte":"Habitants de Valmont, vous qui ne dites rien"}]},{"enonce":"Pourquoi une telle affiche circule-t-elle « clandestinement » ?","aide":"Que risque celui qui accuse le pouvoir ?","type":"choix","options":[{"id":"a","texte":"Parce que personne n’est intéressé"},{"id":"b","texte":"Parce qu’elle ne contient aucun argument"},{"id":"c","texte":"Parce qu’elle est trop courte pour être imprimée"},{"id":"d","texte":"Parce que celui qui la diffuse risque d’être arrêté"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m0"]},"explication":"Le mot **Habitants** interpelle directement les lecteurs : c’est une apostrophe."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c2","i2":"c3","i3":"c0"}},"explication":"Apostrophe : on interpelle. Anaphore : « On a fermé » revient. Question rhétorique : pas de réponse attendue. Je et nous : une voix devient collective."},{"cle":{"type":"choix","ids":["d"]},"explication":"Un texte engagé **prend un risque** : ici, celui d’être arrêté. Il circule donc à voix basse."}]$ex$::jsonb),
  ('892c15e7-cd53-5fc4-b69f-2c9159171431'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le Grand Coq et la fauvette","competence":"argumenter","situation":"Un auteur qui n’ose pas accuser directement peut passer par un détour. Voici une fable écrite pour l’exercice.","documents":[{"id":"fable","type":"texte","genre":"recit","titre":"Le Grand Coq","blocs":["Au royaume des poulaillers, le Grand Coq avait interdit le chant du matin. « Qui chante sans ma permission ira à la marmite ! » criait-il chaque jour du haut de son tas de fumier.","Les poules baissèrent la tête, et plus personne ne chanta. Un matin pourtant, une petite fauvette, qui ne dépendait d’aucun poulailler, se posa sur le toit et chanta si fort que tout le royaume se réveilla."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche le **verbe** qui dit ce que le Grand Coq a fait du chant.","aide":"Quel verbe signifie « défendre de » ?","type":"zone","document":"fable","multiple":false},{"enonce":"Qui le Grand Coq représente-t-il ?","aide":"Qui, dans la vraie vie, peut interdire le chant, c’est-à-dire la parole ?","type":"choix","options":[{"id":"a","texte":"Un pouvoir qui interdit de parler"},{"id":"b","texte":"Un simple éleveur de volailles"},{"id":"c","texte":"Un ami des poules"},{"id":"d","texte":"Un artiste"}],"multiple":false},{"enonce":"Range chaque forme : dit-elle les choses directement, ou par le détour de la fiction ?","aide":"La fable, le conte et la science-fiction inventent une histoire.","type":"categories","categories":[{"id":"c0","texte":"Dire directement"},{"id":"c1","texte":"Passer par la fiction"}],"items":[{"id":"i0","texte":"Pamphlet"},{"id":"i1","texte":"Conte"},{"id":"i2","texte":"Science-fiction"},{"id":"i3","texte":"Fable"},{"id":"i4","texte":"Lettre ouverte"}]},{"enonce":"Complète le bilan de cette fable.","aide":"Le détour protège l’auteur ; quel est son risque ?","type":"trous","segments":["En passant par la ",0,", l’auteur se protège, mais le ",1," peut se perdre."],"banque":["censure","procès","message","fiction"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m8"]},"explication":"Le Grand Coq a **interdit** le chant : c’est la censure de la parole."},{"cle":{"type":"choix","ids":["a"]},"explication":"Le Grand Coq représente **un pouvoir qui interdit de parler** ; la fauvette, celle ou celui qui ose dire la vérité."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c1","i3":"c1","i4":"c0"}},"explication":"Lettre ouverte et pamphlet sont **frontaux** ; fable, conte et science-fiction passent par **la fiction**."},{"cle":{"type":"trous","trous":[["fiction"],["message"]]},"affichage":"fiction · message","explication":"Le détour par la **fiction** protège l’auteur, mais le **message** peut se perdre si le lecteur ne comprend pas."}]$ex$::jsonb),
  ('892c15e7-cd53-5fc4-b69f-2c9159171431'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Trois auteurs, un même courage","competence":"argumenter","situation":"Pour préparer un exposé, Imane a relevé dans un tableau trois écrivains engagés, puis elle a retrouvé une tribune écrite pour l’exercice.","documents":[{"id":"auteurs","type":"tableau","titre":"Écrivains engagés","colonnes":["Auteur","Œuvre","Sa cause","Son risque"],"lignes":[["Hugo","Les Châtiments","Contre Napoléon III","L’exil"],["Zola","« J’accuse… ! »","Défendre Dreyfus","Un procès et l’exil"],["Vercors","Le Silence de la mer","La Résistance","La clandestinité"]],"enteteLignes":false},{"id":"tribune","type":"texte","genre":"article","titre":"Tribune","blocs":["« On ne savait pas », diront peut-être un jour les habitants de notre ville.","Mais je l’ai vu, et nous sommes nombreux à l’avoir vu. Qui osera dire demain qu’il n’était pas là ?"],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Dans le tableau, touche la case qui donne **le risque de Zola**.","aide":"Zola est sur la deuxième ligne ; le risque est dans la dernière colonne.","type":"zone","document":"auteurs","multiple":false},{"enonce":"Dans la tribune, touche **les deux pronoms** qui alternent entre la voix de l’auteur et celle du groupe.","aide":"Un pronom pour une personne, un autre pour plusieurs.","type":"zone","document":"tribune","multiple":true},{"enonce":"La dernière phrase de la tribune, « Qui osera dire demain qu’il n’était pas là ? », est…","aide":"Attend-on vraiment une réponse à cette question ?","type":"choix","options":[{"id":"a","texte":"une anaphore, qui répète un mot en début de phrase"},{"id":"b","texte":"une antiphrase, qui dit le contraire de ce qu’on pense"},{"id":"c","texte":"une litote, qui dit moins pour suggérer plus"},{"id":"d","texte":"une question rhétorique, qui n’attend pas de réponse"}],"multiple":false},{"enonce":"Sous l’Occupation, signer un pamphlet était très dangereux. Quelle forme Vercors a-t-il choisie pour la Résistance ?","aide":"Regarde la ligne de Vercors dans le tableau.","type":"choix","options":[{"id":"a","texte":"Un article dans un quotidien officiel"},{"id":"b","texte":"Une lettre ouverte signée dans un journal"},{"id":"c","texte":"Un discours à la radio nationale"},{"id":"d","texte":"Un récit publié clandestinement"}],"multiple":false},{"enonce":"Relie chaque œuvre à sa forme.","aide":"Relis les formes de l’engagement dans ton cours.","type":"association","gauche":[{"id":"g0","texte":"Les Châtiments"},{"id":"g1","texte":"« J’accuse… ! »"},{"id":"g2","texte":"Le Silence de la mer"},{"id":"g3","texte":"Liberté"}],"droite":[{"id":"d0","texte":"Un recueil de poèmes"},{"id":"d1","texte":"Un récit clandestin"},{"id":"d2","texte":"Un poème de résistance"},{"id":"d3","texte":"Une lettre ouverte"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c3"]},"explication":"Zola risquait **un procès et l’exil** après « J’accuse… ! »."},{"cle":{"type":"zone","ids":["m14","m19"]},"explication":"**Je** et **nous** : l’alternance transforme une voix en collectif."},{"cle":{"type":"choix","ids":["d"]},"explication":"C’est une **question rhétorique** : elle oblige le lecteur à répondre en lui-même."},{"cle":{"type":"choix","ids":["d"]},"explication":"Vercors a publié **Le Silence de la mer**, un récit diffusé clandestinement : la fiction protégeait l’auteur."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g3":"d2","g1":"d3"}},"explication":"Hugo a écrit des poèmes, Zola une lettre ouverte, Vercors un récit, Éluard un poème de résistance."}]$ex$::jsonb),
  ('ab33a95d-97e6-5520-9f94-6af8f9040807'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Léo part pour la montagne","competence":"manier-langue","situation":"Léo annonce son départ à sa famille. Chaque personnage rapporte une parole d’une façon différente.","documents":[{"id":"depart","type":"texte","genre":"recit","titre":"Un départ","blocs":["Léo rentra du collège en courant et dit : « Je pars demain pour la montagne ! »","Sa mère répondit qu’elle le conduirait à la gare le lendemain.","Son père annonça son accord.","Partir demain… Il n’en avait plus si envie, finalement. Et si on se moquait de lui là-haut ?"],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche le **verbe de parole** qui introduit les paroles de Léo.","aide":"Cherche le verbe juste avant les guillemets.","type":"zone","document":"depart","multiple":false},{"enonce":"Range chaque passage selon la façon dont les paroles sont rapportées.","aide":"Guillemets ? Subordonnée en « que » ? Un simple verbe ? Aucun signe ?","type":"categories","categories":[{"id":"c0","texte":"Discours direct"},{"id":"c1","texte":"Discours indirect"},{"id":"c2","texte":"Discours narrativisé"},{"id":"c3","texte":"Discours indirect libre"}],"items":[{"id":"i0","texte":"Son père annonça son accord."},{"id":"i1","texte":"Sa mère répondit qu’elle le conduirait à la gare le lendemain."},{"id":"i2","texte":"« Je pars demain pour la montagne ! »"},{"id":"i3","texte":"Et si on se moquait de lui là-haut ?"}]},{"enonce":"Quel passage permet de connaître les pensées de Léo sans qu’il ouvre la bouche ?","aide":"Quel passage n’a ni guillemets ni « que » ?","type":"choix","options":[{"id":"a","texte":"Le troisième paragraphe"},{"id":"b","texte":"Le dernier paragraphe"},{"id":"c","texte":"Le deuxième paragraphe"},{"id":"d","texte":"Le premier paragraphe"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m7"]},"explication":"Le verbe **dit** introduit la réplique de Léo, rapportée entre guillemets."},{"cle":{"type":"categories","items":{"i0":"c2","i1":"c1","i2":"c0","i3":"c3"}},"explication":"Direct : guillemets. Indirect : « que ». Narrativisé : un simple verbe (« annonça »). Indirect libre : ni guillemets ni « que », on entend la pensée."},{"cle":{"type":"choix","ids":["b"]},"explication":"Le **discours indirect libre** du dernier paragraphe laisse entendre la pensée de Léo."}]$ex$::jsonb),
  ('ab33a95d-97e6-5520-9f94-6af8f9040807'::uuid, 2, 2, 10, 35, 3,
   $ex${"titre":"Le sac oublié","competence":"manier-langue","situation":"Tom et Inès échangent des SMS. Tu vas transformer leurs paroles en discours indirect, comme dans un récit au passé.","documents":[{"id":"sms","type":"dialogue","modele":"sms","participants":[{"nom":"Tom","emoji":"👦","cote":"gauche"},{"nom":"Inès","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Tom","texte":"J’ai oublié mon sac chez toi hier."},{"qui":"Inès","texte":"Pas de souci ! Tu peux passer quand tu veux."},{"qui":"Tom","texte":"Je viendrai le chercher demain matin."}]}],"questions":[{"enonce":"Transpose le premier message de Tom au discours indirect.","aide":"Le passé composé devient un plus-que-parfait ; « hier » devient « la … ».","type":"trous","segments":["Tom a dit à Inès qu’il ",0," oublié son sac chez elle la ",1,"."],"banque":["avait","hier","avais","lendemain","a","veille"]},{"enonce":"Transpose le dernier message de Tom.","aide":"Le futur devient un conditionnel ; « demain » devient « le … ».","type":"trous","segments":["Il a ajouté qu’il ",0," chercher son sac le ",1," matin."],"banque":["demain","lendemain","viendra","venait","veille","viendrait"]},{"enonce":"Inès écrivait : « Tu es sûr ?! » Quelle phrase rapporte correctement ses paroles ?","aide":"L’interrogation devient une subordonnée en « si », sans point d’interrogation.","type":"choix","options":[{"id":"a","texte":"Elle lui demanda s’il en était sûr."},{"id":"b","texte":"Elle lui demanda que tu es sûr."},{"id":"c","texte":"Elle lui demanda s’il est sûr tu ?"},{"id":"d","texte":"Elle lui demanda qu’il est sûr."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"trous","trous":[["avait"],["veille"]]},"affichage":"avait · veille","explication":"« J’ai oublié » devient **avait** oublié, et « hier » devient **la veille**."},{"cle":{"type":"trous","trous":[["viendrait"],["lendemain"]]},"affichage":"viendrait · lendemain","explication":"« Je viendrai » devient il **viendrait** et « demain » devient **le lendemain**."},{"cle":{"type":"choix","ids":["a"]},"explication":"Au discours indirect, une question devient une subordonnée en **si** : « Elle lui demanda s’il en était sûr. » La ponctuation expressive disparaît."}]$ex$::jsonb),
  ('ab33a95d-97e6-5520-9f94-6af8f9040807'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Emma et la promotion","competence":"manier-langue","situation":"Un extrait écrit pour l’exercice, à la manière de Flaubert, et la fiche d’un élève qui résume les effets des types de discours.","documents":[{"id":"emma","type":"texte","genre":"recit","titre":"Emma rentre de la ville","blocs":["Emma rentra de la ville, le panier au bras. Son mari lui annonça sa promotion.","Elle dit : « Tant mieux ! »","Une promotion ! Et pour quoi faire, grand Dieu ? Encore deux ans dans ce trou, à se dire que demain serait pareil à hier.","Elle lui répondit qu’elle était fatiguée."],"source":"Texte écrit pour l’exercice"},{"id":"effets","type":"tableau","titre":"Les effets des types de discours","colonnes":["Type","Effet"],"lignes":[["Direct","Vivacité : on entend la voix"],["Indirect","Mise à distance"],["Indirect libre","On ne sait plus qui parle"],["Narrativisé","?"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le **verbe** qui rapporte la parole du mari en la résumant, sans la citer.","aide":"Le mari parle, mais aucun mot de lui n’est cité.","type":"zone","document":"emma","multiple":false},{"enonce":"Range chaque passage selon le type de discours.","aide":"Le discours indirect libre garde l’exclamation et l’interrogation du personnage.","type":"categories","categories":[{"id":"c0","texte":"Direct"},{"id":"c1","texte":"Indirect"},{"id":"c2","texte":"Indirect libre"},{"id":"c3","texte":"Narrativisé"}],"items":[{"id":"i0","texte":"Elle lui répondit qu’elle était fatiguée."},{"id":"i1","texte":"Son mari lui annonça sa promotion."},{"id":"i2","texte":"Elle dit : « Tant mieux ! »"},{"id":"i3","texte":"Et pour quoi faire, grand Dieu ?"}]},{"enonce":"Pourquoi le discours indirect libre est-il ici plus expressif que « Elle se dit qu’elle s’ennuyait » ?","aide":"Qui parle dans « Et pour quoi faire, grand Dieu ? »","type":"choix","options":[{"id":"a","texte":"Parce qu’on entend la voix d’Emma dans le récit du narrateur"},{"id":"b","texte":"Parce qu’il supprime tout verbe et ne garde que des noms"},{"id":"c","texte":"Parce qu’il cite mot pour mot les paroles du mari d’Emma"},{"id":"d","texte":"Parce qu’il est plus court et plus rapide à lire pour le lecteur"}],"multiple":false},{"enonce":"Dans le tableau, quel effet complète la case « ? » du discours narrativisé ?","aide":"La parole n’est qu’un simple verbe.","type":"choix","options":[{"id":"a","texte":"La mise à distance"},{"id":"b","texte":"La vivacité"},{"id":"c","texte":"La rapidité"},{"id":"d","texte":"L’ambiguïté"}],"multiple":false},{"enonce":"Transpose : « Demain, je partirai. »","aide":"« Demain » devient « le … » et le futur devient un conditionnel.","type":"trous","segments":["Elle dit que le ",0,", elle ",1,"."],"banque":["partait","veille","lendemain","partirait","partira"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m12"]},"explication":"« Son mari lui **annonça** sa promotion » : la parole est résumée par un simple verbe."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c3","i2":"c0","i3":"c2"}},"explication":"Le troisième paragraphe est au **discours indirect libre** : l’exclamation et la question sont d’Emma, mais sans guillemets ni « que »."},{"cle":{"type":"choix","ids":["a"]},"explication":"Le **discours indirect libre** fait entendre la voix d’Emma à travers celle du narrateur : on ne sait plus qui parle."},{"cle":{"type":"choix","ids":["c"]},"explication":"Le discours narrativisé résume la parole en un verbe : il produit **la rapidité**."},{"cle":{"type":"trous","trous":[["lendemain"],["partirait"]]},"affichage":"lendemain · partirait","explication":"« Demain » devient **le lendemain** et le futur devient **partirait**."}]$ex$::jsonb),
  ('07dab06b-f220-55d0-8f2f-766878bd8156'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le grenier de Noé","competence":"analyser-texte","situation":"Noé monte seul au grenier de sa grand-mère. Regarde par les yeux de qui le lecteur découvre la scène.","documents":[{"id":"grenier","type":"texte","genre":"recit","titre":"Dans le grenier","blocs":["Noé entra dans le grenier. Il lui sembla entendre un pas.","Il crut voir une ombre derrière la malle. Était-ce le vent ? Il n’aurait su le dire."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche **les deux verbes** qui montrent que le lecteur voit la scène par les yeux de Noé.","aide":"Cherche ce que Noé croit voir ou entendre.","type":"zone","document":"grenier","multiple":true},{"enonce":"Quelle est la focalisation de ce passage ?","aide":"Le lecteur en sait-il plus que Noé, ou autant que lui ?","type":"choix","options":[{"id":"a","texte":"Externe"},{"id":"b","texte":"Il n’y en a pas"},{"id":"c","texte":"Zéro"},{"id":"d","texte":"Interne"}],"multiple":false},{"enonce":"Que sait le lecteur de l’ombre derrière la malle ?","aide":"Le narrateur dit-il ce qu’est l’ombre ?","type":"choix","options":[{"id":"a","texte":"Que c’est la grand-mère"},{"id":"b","texte":"Que c’est le vent"},{"id":"c","texte":"Rien de plus que Noé"},{"id":"d","texte":"Que c’est un voleur"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m7","m12"]},"explication":"**Sembla** et **crut** sont des verbes de perception : ils donnent le point de vue d’un seul personnage."},{"cle":{"type":"choix","ids":["d"]},"explication":"La focalisation est **interne** : on ne sait que ce que Noé perçoit, avec ses doutes."},{"cle":{"type":"choix","ids":["c"]},"explication":"Le lecteur **n’en sait pas plus que Noé** : c’est ce qui crée le suspense."}]$ex$::jsonb),
  ('07dab06b-f220-55d0-8f2f-766878bd8156'::uuid, 2, 2, 10, 35, 3,
   $ex${"titre":"Le facteur de la famille Morel","competence":"analyser-texte","situation":"Une même scène est racontée trois fois, avec trois points de vue différents. Lis chaque version.","documents":[{"id":"trois","type":"texte","genre":"recit","titre":"Trois versions","blocs":["Le facteur sonna à la porte des Morel. Il ne savait pas que la lettre qu’il portait annoncerait la ruine de la famille, ni que Mme Morel, derrière la porte, pensait déjà à vendre la maison.","Mme Morel vit le facteur par la fenêtre. Son cœur se serra : elle reconnut l’enveloppe, celle de la banque.","Le facteur sonna. La porte s’ouvrit. Une femme prit l’enveloppe sans un mot, ses mains tremblaient, puis elle referma."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Dans le premier paragraphe, touche **le verbe** qui annonce un avenir que le facteur ignore.","aide":"Cherche un verbe au conditionnel, qui parle de la suite.","type":"zone","document":"trois","multiple":false},{"enonce":"Relie chaque paragraphe à sa focalisation.","aide":"Qui sait quoi ? Le narrateur, Mme Morel, ou personne ?","type":"association","gauche":[{"id":"g0","texte":"Premier paragraphe"},{"id":"g1","texte":"Deuxième paragraphe"},{"id":"g2","texte":"Troisième paragraphe"}],"droite":[{"id":"d0","texte":"Focalisation interne"},{"id":"d1","texte":"Focalisation externe"},{"id":"d2","texte":"Focalisation zéro"}]},{"enonce":"Dans le troisième paragraphe, pourquoi ne sait-on pas ce que ressent la femme ?","aide":"Que lit-on : des pensées ou des gestes ?","type":"choix","options":[{"id":"a","texte":"Le narrateur connaît ses pensées mais les cache"},{"id":"b","texte":"Le texte est au passé simple"},{"id":"c","texte":"Le narrateur ne décrit que ce qu’on voit, comme une caméra"},{"id":"d","texte":"La femme est un personnage secondaire"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m18"]},"explication":"Le verbe **annoncerait** montre que le narrateur connaît l’avenir : c’est la focalisation zéro."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"1 : le narrateur sait tout (zéro). 2 : on partage les pensées de Mme Morel (interne). 3 : on ne voit que des gestes, comme une caméra (externe)."},{"cle":{"type":"choix","ids":["c"]},"explication":"On ne lit que des **gestes** : c’est la focalisation externe, qui crée le mystère."}]$ex$::jsonb),
  ('07dab06b-f220-55d0-8f2f-766878bd8156'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le vélo dans le garage","competence":"analyser-texte","situation":"Jules et Anna se disputent. Le récit donne d’abord la version de Jules, puis celle d’Anna. Tu vas croiser les deux.","documents":[{"id":"jules","type":"texte","genre":"recit","titre":"Version de Jules","blocs":["Jules vit Anna ranger le vélo dans le garage. Elle avait pris son vélo sans rien demander, il en était sûr : elle voulait l’humilier devant les autres. Il serra les poings."],"source":"Texte écrit pour l’exercice"},{"id":"anna","type":"texte","genre":"recit","titre":"Version d’Anna","blocs":["Anna rangeait le vélo de Jules dans le garage. Il pleuvait, et elle voulait juste le mettre à l’abri. Elle ne comprenait pas pourquoi Jules la regardait avec cette colère."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Quelle focalisation trouve-t-on dans chacune des deux versions ?","aide":"Dans chaque texte, de qui connaît-on les pensées ?","type":"choix","options":[{"id":"a","texte":"Interne dans la première, zéro dans la seconde"},{"id":"b","texte":"Interne, mais avec un personnage différent"},{"id":"c","texte":"Zéro dans les deux"},{"id":"d","texte":"Externe dans la première, interne dans la seconde"}],"multiple":false},{"enonce":"Dans la version de Jules, touche **le mot** qui montre que c’est sa conviction, pas un fait établi.","aide":"Cherche l’adjectif qui dit que Jules est certain.","type":"zone","document":"jules","multiple":false},{"enonce":"Dans la version d’Anna, touche **le verbe** qui montre qu’elle ignore ce que pense Jules.","aide":"Quel verbe dit qu’elle ne saisit pas la situation ?","type":"zone","document":"anna","multiple":false},{"enonce":"Range chaque affirmation : dans quelle version est-elle vraie ?","aide":"Un fait commun apparaît dans les deux textes.","type":"categories","categories":[{"id":"c0","texte":"Selon Jules"},{"id":"c1","texte":"Selon Anna"},{"id":"c2","texte":"Dans les deux versions"}],"items":[{"id":"i0","texte":"Jules est en colère"},{"id":"i1","texte":"Anna a pris le vélo pour humilier Jules"},{"id":"i2","texte":"Anna voulait mettre le vélo à l’abri de la pluie"},{"id":"i3","texte":"Le vélo est rangé dans le garage"}]},{"enonce":"Pourquoi le lecteur qui lit les deux versions en sait-il plus que chaque personnage ?","aide":"Chaque personnage ne connaît qu’une partie de l’histoire.","type":"choix","options":[{"id":"a","texte":"Il connaît déjà l’avenir des personnages grâce au titre"},{"id":"b","texte":"Il lit un seul texte écrit en focalisation zéro, donc omniscient"},{"id":"c","texte":"Il reconstitue le puzzle à partir de deux vérités partielles"},{"id":"d","texte":"Le narrateur lui donne toute la solution à la fin du second récit"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["b"]},"explication":"Chaque version est en focalisation **interne**, mais le personnage change : Jules, puis Anna."},{"cle":{"type":"zone","ids":["m20"]},"explication":"Jules est **sûr** : c’est sa conviction, que rien ne prouve."},{"cle":{"type":"zone","ids":["m22"]},"explication":"Anna ne **comprenait** pas : elle n’a accès qu’à ce qu’elle voit de Jules."},{"cle":{"type":"categories","items":{"i0":"c2","i1":"c0","i2":"c1","i3":"c2"}},"explication":"Le vélo dans le garage et la colère de Jules sont dans les deux versions ; l’intention d’Anna diffère selon qui raconte."},{"cle":{"type":"choix","ids":["c"]},"explication":"En alternant les points de vue, le roman donne au lecteur **deux vérités partielles** : c’est lui qui reconstitue le puzzle."}]$ex$::jsonb),
  ('e1c93b4c-38f0-586f-9427-b59e0e693997'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"La nuit sur la lande","competence":"analyser-texte","situation":"Dans un récit, le décor et l’action n’utilisent pas les mêmes temps. Observe cet extrait écrit pour l’exercice.","documents":[{"id":"lande","type":"texte","genre":"recit","titre":"Une nuit sur la lande","blocs":["La nuit tombait sur la lande et le vent soufflait dans les sapins. Soudain, un cri retentit. Mathis saisit sa lampe, sortit et courut vers la grange."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche les **quatre verbes au passé simple**.","aide":"Le passé simple fait avancer l’action : cherche les verbes après « Soudain ».","type":"zone","document":"lande","multiple":true},{"enonce":"Range chaque verbe : décor ou action ?","aide":"Le décor dure, l’événement surgit.","type":"categories","categories":[{"id":"c0","texte":"Imparfait (le décor)"},{"id":"c1","texte":"Passé simple (l’action)"}],"items":[{"id":"i0","texte":"courut"},{"id":"i1","texte":"tombait"},{"id":"i2","texte":"retentit"},{"id":"i3","texte":"soufflait"}]},{"enonce":"Touche le mot qui signale **le moment où le récit bascule** du décor à l’action.","aide":"Quel adverbe annonce quelque chose de brusque ?","type":"zone","document":"lande","multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m16","m18","m21","m23"]},"explication":"Les verbes au passé simple sont **retentit, saisit, sortit, courut** : les actions qui s’enchaînent."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c1","i3":"c0"}},"explication":"**Tombait** et **soufflait** (imparfait) installent le décor ; **retentit** et **courut** (passé simple) font avancer l’histoire."},{"cle":{"type":"zone","ids":["m13"]},"explication":"**Soudain** marque la rupture : le temps change, l’événement surgit."}]$ex$::jsonb),
  ('e1c93b4c-38f0-586f-9427-b59e0e693997'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Les étés chez grand-mère","competence":"analyser-texte","situation":"Un narrateur se souvient de ses vacances. Observe les valeurs de l’imparfait et la façon dont le passé simple les interrompt.","documents":[{"id":"etes","type":"texte","genre":"recit","titre":"Souvenirs d’été","blocs":["Chaque été, nous partions chez ma grand-mère.","Sa maison était perchée au bout d’un chemin, et un grand noyer ombrageait la cour.","Un après-midi, nous jouions aux billes quand l’orage éclata.","Aujourd’hui, si j’avais le temps, j’y retournerais."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Range chaque phrase selon la valeur de l’imparfait.","aide":"Une action répétée ? un décor ? une action interrompue ? un « si » ?","type":"categories","categories":[{"id":"c0","texte":"Habitude"},{"id":"c1","texte":"Description"},{"id":"c2","texte":"Rupture"},{"id":"c3","texte":"Hypothèse"}],"items":[{"id":"i0","texte":"Si j’avais le temps, j’y retournerais"},{"id":"i1","texte":"Chaque été, nous partions chez ma grand-mère"},{"id":"i2","texte":"Nous jouions aux billes quand l’orage éclata"},{"id":"i3","texte":"Un grand noyer ombrageait la cour"}]},{"enonce":"Touche **le verbe à l’imparfait** qui est interrompu par un événement.","aide":"Quel verbe décrit une action en cours, coupée net ?","type":"zone","document":"etes","multiple":false},{"enonce":"Touche **le verbe au passé simple** qui interrompt cette action.","aide":"Cherche le verbe qui décrit l’orage.","type":"zone","document":"etes","multiple":false},{"enonce":"Que produit le passage de l’imparfait au passé simple dans la troisième phrase ?","aide":"Qu’est-ce qui dure, qu’est-ce qui surgit ?","type":"choix","options":[{"id":"a","texte":"L’événement surgit sur une action qui durait"},{"id":"b","texte":"Le décor devient plus précis et plus détaillé"},{"id":"c","texte":"Le narrateur donne son avis sur ce qui arrive"},{"id":"d","texte":"L’action se répète chaque été, comme une habitude"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"categories","items":{"i0":"c3","i1":"c0","i2":"c2","i3":"c1"}},"explication":"Habitude : « chaque été ». Description : le noyer. Rupture : une action longue interrompue. Hypothèse : le « si »."},{"cle":{"type":"zone","ids":["m26"]},"explication":"**Jouions** est interrompu par l’orage : c’est un imparfait de rupture."},{"cle":{"type":"zone","ids":["m32"]},"explication":"**Éclata** est le passé simple : l’événement brusque qui coupe l’action en cours."},{"cle":{"type":"choix","ids":["a"]},"explication":"L’imparfait installe ce qui **dure**, le passé simple fait **surgir** l’événement : c’est le moteur du récit."}]$ex$::jsonb),
  ('e1c93b4c-38f0-586f-9427-b59e0e693997'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le chirurgien de Valcourt","competence":"analyser-texte","situation":"Un récit fictif écrit pour l’exercice et le panneau de l’hôpital de Valcourt : observe les valeurs du futur.","documents":[{"id":"chirurgien","type":"texte","genre":"recit","titre":"Un destin","blocs":["En 1850, dans la petite ville de Valcourt, naissait un garçon que rien ne destinait à la gloire. Il deviendra pourtant le plus célèbre chirurgien de son temps."],"source":"Texte écrit pour l’exercice"},{"id":"panneau","type":"fiche","modele":"panneau","entete":"Hôpital de Valcourt","sousTitre":"Accueil","emoji":"🏥","teinte":"bleu","lignes":[{"texte":"Le docteur Marin vous recevra à 14 h.","id":"z1"},{"texte":"Nous vous demanderons de patienter quelques instants.","id":"z2"},{"texte":"Quand vous aurez rempli ce formulaire, vous le remettrez à l’accueil.","id":"z3"}],"pied":"Merci de votre patience"}],"questions":[{"enonce":"Dans le récit, touche **le verbe au futur** alors que tout le reste est au passé.","aide":"Cherche le seul verbe qui ne parle pas du passé.","type":"zone","document":"chirurgien","multiple":false},{"enonce":"Sur le panneau, touche la ligne qui emploie **un futur de politesse**.","aide":"Quelle phrase adoucit une demande ?","type":"zone","document":"panneau","multiple":false},{"enonce":"Sur le panneau, touche la ligne qui contient **un futur antérieur**.","aide":"Cherche « aurez » suivi d’un participe passé.","type":"zone","document":"panneau","multiple":false},{"enonce":"Range chaque phrase selon la valeur du futur.","aide":"Regarde si le texte est au passé, et si l’action est achevée.","type":"categories","categories":[{"id":"c0","texte":"Futur simple (prédiction)"},{"id":"c1","texte":"Futur antérieur"},{"id":"c2","texte":"Futur de politesse"},{"id":"c3","texte":"Futur historique"}],"items":[{"id":"i0","texte":"Le docteur vous recevra à 14 h"},{"id":"i1","texte":"Nous vous demanderons de patienter"},{"id":"i2","texte":"Quand vous aurez rempli ce formulaire"},{"id":"i3","texte":"Il deviendra le plus célèbre chirurgien de son temps"}]},{"enonce":"Pour analyser un texte, où faut-il chercher l’information importante ?","aide":"Souviens-toi de la méthode : temps dominant, puis ruptures.","type":"choix","options":[{"id":"a","texte":"Dans le premier mot de chaque phrase"},{"id":"b","texte":"Au moment où le texte change de temps"},{"id":"c","texte":"Dans la longueur des paragraphes"},{"id":"d","texte":"À la fin du dernier paragraphe seulement"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m19"]},"explication":"**Deviendra** est un futur historique : il annonce une suite que le lecteur ignore encore."},{"cle":{"type":"zone","ids":["z2"]},"explication":"« **Nous vous demanderons de patienter** » : le futur adoucit la demande, c’est un futur de politesse."},{"cle":{"type":"zone","ids":["z3"]},"explication":"« **Quand vous aurez rempli** » est un futur antérieur : une action achevée avant une autre à venir."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c2","i2":"c1","i3":"c3"}},"explication":"Prédiction : « recevra ». Antérieur : « aurez rempli ». Politesse : « demanderons ». Historique : « deviendra » dans un récit au passé."},{"cle":{"type":"choix","ids":["b"]},"explication":"C’est presque toujours **quand le texte change de temps** que quelque chose d’important se produit."}]$ex$::jsonb),
  ('5f73a899-2e3b-564a-9b86-31a80bc130b4'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Soir sur les sapins","competence":"analyser-texte","situation":"Voici un petit poème écrit pour l’exercice. Cherche les images que le poète utilise.","documents":[{"id":"soir","type":"texte","genre":"poeme","titre":"Soir","blocs":["Le vent gémit dans les sapins noirs,","Comme un enfant perdu dans le soir.","La nuit est un manteau d’encre,","Et la lune ouvre un œil pâle."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche **le mot outil** qui construit la comparaison.","aide":"Cherche le petit mot qui relie deux réalités.","type":"zone","document":"soir","multiple":false},{"enonce":"Touche **le verbe** qui donne un trait humain au vent (personnification).","aide":"Quel verbe dit un cri de plainte humain ?","type":"zone","document":"soir","multiple":false},{"enonce":"Au vers 3, « La nuit est un manteau d’encre » est…","aide":"Y a-t-il « comme » ou « tel » dans ce vers ?","type":"choix","options":[{"id":"a","texte":"une litote"},{"id":"b","texte":"une métaphore"},{"id":"c","texte":"un euphémisme"},{"id":"d","texte":"une comparaison"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m7"]},"explication":"**Comme** est l’outil de la comparaison : le vent est comparé à un enfant."},{"cle":{"type":"zone","ids":["m2"]},"explication":"Le vent **gémit** comme une personne : c’est une personnification."},{"cle":{"type":"choix","ids":["b"]},"explication":"Il n’y a **pas d’outil de comparaison** : c’est une métaphore."}]$ex$::jsonb),
  ('5f73a899-2e3b-564a-9b86-31a80bc130b4'::uuid, 2, 2, 10, 35, 3,
   $ex${"titre":"Le carnet de Maya","competence":"analyser-texte","situation":"Maya raconte sa semaine dans son carnet (texte écrit pour l’exercice). Elle utilise des figures de style très courantes.","documents":[{"id":"carnet","type":"texte","genre":"recit","titre":"Extraits du carnet","blocs":["J’ai attendu mille ans devant la cantine.","Ce gâteau n’est pas mauvais du tout.","Mon grand-père nous a quittés l’an dernier.","Dans la salle, il régnait un silence assourdissant.","L’astre du jour se levait derrière les toits."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Relie chaque extrait à sa figure.","aide":"Exagération, dire moins, adoucir, deux contraires, plusieurs mots pour un seul.","type":"association","gauche":[{"id":"g0","texte":"J’ai attendu mille ans"},{"id":"g1","texte":"Ce gâteau n’est pas mauvais du tout"},{"id":"g2","texte":"Il nous a quittés"},{"id":"g3","texte":"Un silence assourdissant"},{"id":"g4","texte":"L’astre du jour"}],"droite":[{"id":"d0","texte":"Périphrase"},{"id":"d1","texte":"Euphémisme"},{"id":"d2","texte":"Litote"},{"id":"d3","texte":"Hyperbole"},{"id":"d4","texte":"Oxymore"}]},{"enonce":"Touche **les deux mots** qui forment un oxymore.","aide":"Un nom et un adjectif qui se contredisent.","type":"zone","document":"carnet","multiple":true},{"enonce":"Quel est l’effet de « J’ai attendu mille ans » ?","aide":"Maya a-t-elle vraiment attendu mille ans ?","type":"choix","options":[{"id":"a","texte":"Il fait sentir l’impatience en exagérant"},{"id":"b","texte":"Il donne une date précise de l’attente"},{"id":"c","texte":"Il adoucit une réalité pénible par un euphémisme"},{"id":"d","texte":"Il décrit un paysage à la manière d’un peintre"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"association","paires":{"g4":"d0","g2":"d1","g1":"d2","g0":"d3","g3":"d4"}},"explication":"Mille ans : exagération. Pas mauvais du tout : on dit moins pour suggérer plus. Quittés : adoucit la mort. Silence assourdissant : deux termes contradictoires. Astre du jour : le soleil en plusieurs mots."},{"cle":{"type":"zone","ids":["m30","m31"]},"explication":"**Silence** et **assourdissant** se contredisent : c’est un oxymore."},{"cle":{"type":"choix","ids":["a"]},"explication":"L’**hyperbole** exagère pour faire sentir l’impatience : c’est l’effet qu’il faut toujours préciser."}]$ex$::jsonb),
  ('5f73a899-2e3b-564a-9b86-31a80bc130b4'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Sur les quais","competence":"analyser-texte","situation":"Voici un poème écrit pour l’exercice et la réponse de Jade à une question d’analyse. Il te faudra repérer, nommer et interpréter.","documents":[{"id":"quais","type":"texte","genre":"poeme","titre":"Sur les quais","blocs":["Sur les quais, on rit, on crie, on hurle ;","Sur les quais, la ville est un feu qui s’étire ;","Nous vivons pour danser, nous dansons pour vivre."],"source":"Texte écrit pour l’exercice"},{"id":"copie","type":"texte","genre":"consigne","titre":"La réponse de Jade","blocs":["« Au vers 3, on trouve un chiasme. »"],"source":"Réponse d’élève écrite pour l’exercice"}],"questions":[{"enonce":"Touche **les trois verbes** qui forment une gradation.","aide":"Trois verbes dont la force augmente.","type":"zone","document":"quais","multiple":true},{"enonce":"Au vers 2, touche **le mot** qui montre que la ville est comparée à autre chose sans outil de comparaison.","aide":"Quel nom désigne l’image ?","type":"zone","document":"quais","multiple":false},{"enonce":"Quelle figure structure le vers 3, « Nous vivons pour danser, nous dansons pour vivre » ?","aide":"Regarde comment les verbes « vivre » et « danser » sont croisés.","type":"choix","options":[{"id":"a","texte":"Un oxymore"},{"id":"b","texte":"Une gradation"},{"id":"c","texte":"Une litote"},{"id":"d","texte":"Un chiasme"}],"multiple":false},{"enonce":"Que manque-t-il à la réponse de Jade pour être complète ?","aide":"Souviens-toi de la méthode : je repère, je nomme, j’…","type":"choix","options":[{"id":"a","texte":"Un deuxième exemple pris dans un autre passage"},{"id":"b","texte":"Le nom du poète et quelques dates de sa vie"},{"id":"c","texte":"La date de publication du poème et son siècle"},{"id":"d","texte":"L’interprétation : l’effet produit dans le poème"}],"multiple":false},{"enonce":"Complète une interprétation du chiasme.","aide":"Le vers dit : vivre pour danser, danser pour vivre.","type":"trous","segments":["Le chiasme montre que danser et ",0," sont ",1,"."],"banque":["inséparables","ennuyeux","vivre","opposés"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m4","m6","m8"]},"explication":"**Rit, crie, hurle** : l’intensité monte, c’est une gradation."},{"cle":{"type":"zone","ids":["m16"]},"explication":"La ville « est un **feu** » : c’est une métaphore, sans « comme »."},{"cle":{"type":"choix","ids":["d"]},"explication":"Les termes sont croisés (**vivons – danser / dansons – vivre**) : c’est un chiasme."},{"cle":{"type":"choix","ids":["d"]},"explication":"Jade a repéré et nommé, mais il lui faut **interpréter** l’effet dans ce texte-ci."},{"cle":{"type":"trous","trous":[["vivre"],["inseparables"]]},"affichage":"vivre · inséparables","explication":"Le chiasme lie **vivre** et danser : ils sont **inséparables**, chacun sert l’autre."}]$ex$::jsonb),
  ('79361f6a-893c-50e5-a3da-b9eadb00bca8'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Lire vingt minutes par jour","competence":"argumenter","situation":"Léna défend une idée dans un court texte écrit pour l’exercice. Repère comment il est construit.","documents":[{"id":"lecture","type":"texte","genre":"article","titre":"Pour la lecture","blocs":["À mon avis, tous les collégiens devraient lire chaque jour.","La lecture enrichit en effet le vocabulaire.","Ainsi, Samir, qui lit un roman par semaine, a obtenu la meilleure note en rédaction.","Certes, un film peut aussi faire rêver. Mais il ne fait pas travailler la langue."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche **le mot** qui annonce une concession dans le dernier paragraphe.","aide":"Quel mot reconnaît une part de vérité à l’adversaire ?","type":"zone","document":"lecture","multiple":false},{"enonce":"Range chaque phrase selon son rôle dans le texte.","aide":"La thèse est l’opinion ; l’exemple est un fait précis avec un nom.","type":"categories","categories":[{"id":"c0","texte":"Thèse"},{"id":"c1","texte":"Argument"},{"id":"c2","texte":"Exemple"},{"id":"c3","texte":"Concession"}],"items":[{"id":"i0","texte":"Tous les collégiens devraient lire chaque jour"},{"id":"i1","texte":"Samir, qui lit un roman par semaine, a eu la meilleure note en rédaction"},{"id":"i2","texte":"Un film peut aussi faire rêver"},{"id":"i3","texte":"La lecture enrichit le vocabulaire"}]},{"enonce":"Touche le **prénom** qui montre qu’on est devant un exemple précis.","aide":"Un exemple est un fait précis : cherche une personne nommée.","type":"zone","document":"lecture","multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m32"]},"explication":"**Certes** annonce la concession : on reconnaît que le film fait rêver, avant de réfuter avec « mais »."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c2","i2":"c3","i3":"c1"}},"explication":"Thèse : l’opinion défendue. Argument : la raison (vocabulaire). Exemple : le cas de Samir. Concession : le film fait rêver."},{"cle":{"type":"zone","ids":["m18"]},"explication":"Le prénom **Samir** fait de la phrase un exemple précis, pas une idée générale."}]$ex$::jsonb),
  ('79361f6a-893c-50e5-a3da-b9eadb00bca8'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"À vélo jusqu’au collège","competence":"argumenter","situation":"Un élève défend une idée dans un court texte écrit pour l’exercice. Tu vas repérer ses connecteurs et reconstituer son plan.","documents":[{"id":"velo","type":"texte","genre":"article","titre":"Le vélo au collège","blocs":["Venir au collège à vélo devrait être encouragé.","Certes, il pleut souvent et le trajet peut fatiguer.","Mais le vélo garde les élèves en forme, car l’exercice du matin réveille le corps.","Ainsi, la classe de Mme Duval, qui roule ensemble chaque vendredi, arrive plus attentive."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche **le connecteur** qui annonce la concession.","aide":"Quel mot reconnaît un défaut du vélo ?","type":"zone","document":"velo","multiple":false},{"enonce":"Range chaque connecteur du texte selon le lien qu’il exprime.","aide":"Un connecteur de cause répond à « pourquoi ? ».","type":"categories","categories":[{"id":"c0","texte":"Concession"},{"id":"c1","texte":"Opposition"},{"id":"c2","texte":"Cause"},{"id":"c3","texte":"Conséquence"}],"items":[{"id":"i0","texte":"car"},{"id":"i1","texte":"Certes"},{"id":"i2","texte":"Ainsi"},{"id":"i3","texte":"Mais"}]},{"enonce":"Remets dans l’ordre le mouvement du texte.","aide":"Suis les paragraphes, du premier au dernier.","type":"ordre","items":[{"id":"a","texte":"Annoncer la thèse"},{"id":"b","texte":"Illustrer par un exemple"},{"id":"c","texte":"Faire une concession"},{"id":"d","texte":"Réfuter avec un argument"}]},{"enonce":"La concession « Certes, il pleut souvent… » affaiblit-elle le texte ?","aide":"Qui a l’air le plus sérieux : celui qui écoute l’autre ou celui qui l’ignore ?","type":"choix","options":[{"id":"a","texte":"Oui, elle prouve que la thèse est fausse"},{"id":"b","texte":"Non, elle est sans effet"},{"id":"c","texte":"Non, elle montre qu’on a compris l’autre camp"},{"id":"d","texte":"Oui, elle remplace l’argument"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m8"]},"explication":"**Certes** reconnaît un défaut du vélo avant de le réfuter."},{"cle":{"type":"categories","items":{"i0":"c2","i1":"c0","i2":"c3","i3":"c1"}},"explication":"Certes : concession. Mais : opposition. Car : cause. Ainsi : conséquence."},{"cle":{"type":"ordre","ids":["a","c","d","b"]},"explication":"Le texte annonce sa **thèse**, fait une **concession**, la **réfute** par un argument, puis **illustre** par un exemple."},{"cle":{"type":"choix","ids":["c"]},"explication":"La concession **renforce** le texte : elle montre qu’on a compris le point de vue adverse."}]$ex$::jsonb),
  ('79361f6a-893c-50e5-a3da-b9eadb00bca8'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le Chêne, le Pissenlit et le bruit","competence":"argumenter","situation":"Deux textes écrits pour l’exercice défendent une idée : l’un par une histoire, l’autre directement. Compare-les.","documents":[{"id":"fable","type":"texte","genre":"recit","titre":"Le Chêne et le Pissenlit","blocs":["Au bord d’un champ, un jeune Pissenlit moquait le vieux Chêne : « Tu es lent, tu es lourd, à quoi sers-tu ? » Le Chêne ne répondit pas.","L’orage vint. Le Pissenlit fut arraché par le vent ; le Chêne, lui, abrita toute la clairière."],"source":"Texte écrit pour l’exercice"},{"id":"tribune","type":"texte","genre":"article","titre":"Tribune du quartier","blocs":["Selon un relevé du quartier imaginé pour l’exercice, le bruit y dépasse 70 décibels dès 8 h.","Habitants de la rue des Lilas, voulez-vous vraiment vivre dans ce vacarme ?"],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Dans la fable, touche **le verbe** qui montre l’attitude du Pissenlit envers le Chêne.","aide":"Quel verbe dit qu’il se rit du Chêne ?","type":"zone","document":"fable","multiple":false},{"enonce":"Quelle est la thèse implicite de la fable ?","aide":"Qui a survécu à l’orage, et pourquoi ?","type":"choix","options":[{"id":"a","texte":"Il faut toujours se moquer de ceux qui avancent lentement"},{"id":"b","texte":"Les grands arbres sont toujours supérieurs aux petites fleurs"},{"id":"c","texte":"La solidité et la patience valent mieux que l’agitation"},{"id":"d","texte":"Les orages détruisent tout ce qui pousse dans un jardin"}],"multiple":false},{"enonce":"Dans la tribune, range chaque moyen : convaincre ou persuader ?","aide":"Un chiffre s’adresse à la raison ; une question ou une interpellation, aux sentiments.","type":"categories","categories":[{"id":"c0","texte":"Convaincre"},{"id":"c1","texte":"Persuader"}],"items":[{"id":"i0","texte":"Voulez-vous vraiment vivre dans ce vacarme ?"},{"id":"i1","texte":"Habitants de la rue des Lilas"},{"id":"i2","texte":"Le bruit dépasse 70 décibels dès 8 h"}]},{"enonce":"Quelle forme d’argumentation chacun de ces deux textes emploie-t-il ?","aide":"Un texte dit-il sa thèse, ou la fait-il comprendre par une histoire ?","type":"choix","options":[{"id":"a","texte":"Les deux sont directes"},{"id":"b","texte":"Les deux sont indirectes"},{"id":"c","texte":"La fable est indirecte, la tribune est directe"},{"id":"d","texte":"La fable est directe, la tribune est indirecte"}],"multiple":false},{"enonce":"Dans la tribune, touche **le mot** qui interpelle directement les lecteurs.","aide":"Le premier mot nomme ceux à qui l’on parle.","type":"zone","document":"tribune","multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m8"]},"explication":"Le Pissenlit **moquait** le Chêne : c’est le défaut que la fable va punir."},{"cle":{"type":"choix","ids":["c"]},"explication":"La fable ne dit rien directement : elle fait comprendre que **la solidité et la patience** valent mieux que l’agitation."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0"}},"explication":"Le chiffre **convainc** (raison) ; la question rhétorique et l’apostrophe **persuadent** (sentiments)."},{"cle":{"type":"choix","ids":["c"]},"explication":"La **fable** argumente par un détour (indirecte) ; la **tribune** défend sa thèse en face (directe)."},{"cle":{"type":"zone","ids":["m18"]},"explication":"**Habitants** est une apostrophe : elle interpelle directement les lecteurs."}]$ex$::jsonb),
