   $ex${"titre":"Le soir descend","competence":"analyser-texte","situation":"Voici un quatrain écrit pour l’exercice. Compte, écoute les rimes et donne-lui son vocabulaire.","documents":[{"id":"soir","type":"texte","genre":"poeme","titre":"Le soir descend","blocs":["Le soir descend sur la colline,","La lune blanche se devine ;","Les vents s’endorment dans les pins,","La nuit tombe sur les chemins."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Combien de syllabes compte le **vers 1** (le e muet final ne compte pas) ?","aide":"Le-soir-des-cend-sur-la-col… Continue et n’oublie pas de t’arrêter avant le e muet final.","type":"nombre"},{"enonce":"Touche **le mot** qui rime avec « colline ».","aide":"Cherche un mot qui finit par le même son.","type":"zone","document":"soir","multiple":false},{"enonce":"Quelle est la disposition des rimes de ce quatrain ?","aide":"Quels vers riment entre eux : 1 et 2, ou 1 et 3 ?","type":"choix","options":[{"id":"a","texte":"Rimes embrassées (ABBA)"},{"id":"b","texte":"Rimes croisées (ABAB)"},{"id":"c","texte":"Rimes plates (AABB)"},{"id":"d","texte":"Il n’y a pas de rimes"}],"multiple":false}]}$ex$::jsonb,
