  ('8b446067-fe31-561b-88a0-3fac7d6e768f'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"L’eau du matin","competence":"analyser-texte","situation":"Un quatrain de huit syllabes, écrit pour l’exercice : tu vas compter, repérer les rimes et en donner la richesse.","documents":[{"id":"eau","type":"texte","genre":"poeme","titre":"L’eau du matin","blocs":["Le matin pâle éclaire l’eau,","Les roseaux tremblent doucement ;","Un héron passe, frêle oiseau,","Et le jour naît tranquillement."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Combien de syllabes compte le **vers 2**, « Les roseaux tremblent doucement » ?","aide":"Le e de « tremblent » compte devant une consonne : trem-blent = 2 syllabes.","type":"nombre"},{"enonce":"Quelle est la disposition des rimes de ce quatrain ?","aide":"Le vers 1 rime avec lequel ?","type":"choix","options":[{"id":"a","texte":"Rimes plates (AABB)"},{"id":"b","texte":"Rimes embrassées (ABBA)"},{"id":"c","texte":"Il n’y a pas de rimes"},{"id":"d","texte":"Rimes croisées (ABAB)"}],"multiple":false},{"enonce":"Complète la description de ce poème.","aide":"Quatre vers : quel nom ? Huit syllabes : quel mètre ?","type":"trous","segments":["Ce poème est un ",0," (strophe de quatre vers) écrit en ",1," (vers de huit syllabes)."],"banque":["octosyllabes","tercet","alexandrins","quatrain"]},{"enonce":"Les mots « eau » et « oiseau » partagent un seul son, [o]. Quelle est la richesse de cette rime ?","aide":"Pauvre : 1 son ; suffisante : 2 ; riche : 3 ou plus.","type":"choix","options":[{"id":"a","texte":"Pauvre"},{"id":"b","texte":"Riche"},{"id":"c","texte":"Masculine"},{"id":"d","texte":"Suffisante"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":8,"tolerance":0},"affichage":"8","explication":"Les · ro · seaux · trem · blent · dou · ce · ment : **8 syllabes**, car le e muet de « tremblent » compte devant la consonne d."},{"cle":{"type":"choix","ids":["d"]},"explication":"« eau » rime avec « oiseau » (vers 1 et 3), « doucement » avec « tranquillement » (2 et 4) : **ABAB**."},{"cle":{"type":"trous","trous":[["quatrain"],["octosyllabes"]]},"affichage":"quatrain · octosyllabes","explication":"Quatre vers font un **quatrain** ; huit syllabes, des **octosyllabes**."},{"cle":{"type":"choix","ids":["a"]},"explication":"Un seul son partagé : la rime est **pauvre**."}]$ex$::jsonb),
  ('8b446067-fe31-561b-88a0-3fac7d6e768f'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"La route déserte","competence":"analyser-texte","situation":"Un poème en vers libres, écrit pour l’exercice, et la réponse d’un élève. Tu vas repérer les effets et corriger une erreur.","documents":[{"id":"route","type":"texte","genre":"poeme","titre":"La route déserte","blocs":["Elle est partie ce soir. Je reste sur la route","Déserte. Mon chagrin est un vieux chien qui hurle","Tout seul dans la nuit noire, et le vent qui chuchote","Chante sur les sapins sa chanson de silence."],"source":"Texte écrit pour l’exercice"},{"id":"copie","type":"texte","genre":"consigne","titre":"La phrase d’un élève","blocs":["« Ce poème est un sonnet, car il a quatre vers. »"],"source":"Réponse d’élève écrite pour l’exercice"}],"questions":[{"enonce":"Touche **le mot** rejeté au début du vers 2 : il termine la phrase du vers 1.","aide":"Quel mot bref déborde du vers 1 sur le vers 2 ?","type":"zone","document":"route","multiple":false},{"enonce":"Touche **le mot** qui compare le chagrin à un animal, sans outil de comparaison.","aide":"De quel animal le chagrin est-il l’image ?","type":"zone","document":"route","multiple":false},{"enonce":"Quel registre domine dans ce poème ?","aide":"Le poète exprime-t-il une plainte, un héroïsme, un rire ?","type":"choix","options":[{"id":"a","texte":"Épique"},{"id":"b","texte":"Élégiaque"},{"id":"c","texte":"Comique"},{"id":"d","texte":"Didactique"}],"multiple":false},{"enonce":"Quelle erreur la phrase de l’élève contient-elle ?","aide":"Combien de vers faut-il pour un sonnet ?","type":"choix","options":[{"id":"a","texte":"Un sonnet compte quatorze vers"},{"id":"b","texte":"Un sonnet ne compte que des tercets"},{"id":"c","texte":"Un sonnet est forcément comique"},{"id":"d","texte":"Un sonnet n’a pas de rimes"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m10"]},"explication":"**Déserte** complète « la route » du vers 1 : c’est un rejet."},{"cle":{"type":"zone","ids":["m16"]},"explication":"Le chagrin « est un vieux **chien** qui hurle » : c’est une métaphore."},{"cle":{"type":"choix","ids":["b"]},"explication":"Le poète pleure une absence : le registre est **élégiaque** (plainte, deuil, nostalgie)."},{"cle":{"type":"choix","ids":["a"]},"explication":"Un sonnet compte **14 vers** : deux quatrains puis deux tercets. Ce poème n’est pas un sonnet."}]$ex$::jsonb),
  ('d43b3847-14d9-508a-8445-df7338ba1a66'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Les clés de Gaston","competence":"analyser-texte","situation":"Une petite scène écrite pour l’exercice : observe comment les répliques et les indications scéniques se répartissent.","documents":[{"id":"cles","type":"texte","genre":"theatre","titre":"Scène 2","blocs":[{"didascalie":"Une cuisine. Gaston entre, l’air pressé. Sa sœur Mina écrit à la table."},{"personnage":"Gaston","replique":"Mina, tu n’as pas vu mes clés ?"},{"personnage":"Mina","replique":"Non."},{"personnage":"Gaston","replique":"Et mon portefeuille ?"},{"personnage":"Mina","replique":"Non."},{"didascalie":"Mina, à part, au public : elle cache les clés dans sa poche."},{"personnage":"Mina","replique":"Il ne saura jamais que je les ai prises."}],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Comment s’appelle l’échange de répliques très brèves entre Gaston et Mina ?","aide":"Les répliques sont-elles longues ou très courtes ?","type":"choix","options":[{"id":"a","texte":"Un monologue"},{"id":"b","texte":"Une tirade"},{"id":"c","texte":"Une exposition"},{"id":"d","texte":"Une stichomythie"}],"multiple":false},{"enonce":"Dans la dernière réplique de Mina, que sait le public que Gaston ignore ?","aide":"Lis la didascalie avant la dernière réplique.","type":"choix","options":[{"id":"a","texte":"Que Mina écrit une lettre"},{"id":"b","texte":"Que la scène se passe dans une cuisine"},{"id":"c","texte":"Que Gaston a perdu son portefeuille"},{"id":"d","texte":"Que Mina a caché les clés"}],"multiple":false},{"enonce":"Qu’est-ce que la didascalie « à part, au public » indique ?","aide":"Qui est censé entendre ce qui est dit ?","type":"choix","options":[{"id":"a","texte":"Que la réplique suivante est un aparté, adressé au public"},{"id":"b","texte":"Qu’un nouvel acte commence, avec un autre décor"},{"id":"c","texte":"Que Mina quitte la scène pour changer de costume"},{"id":"d","texte":"Que la scène est terminée et que les acteurs sortent"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["d"]},"explication":"Des répliques très brèves qui se répondent : c’est une **stichomythie**."},{"cle":{"type":"choix","ids":["d"]},"explication":"Mina parle **à part** : le public entend qu’elle a caché les clés, Gaston non. C’est un aparté."},{"cle":{"type":"choix","ids":["a"]},"explication":"« À part » signale un **aparté** : le public entend, pas les autres personnages."}]$ex$::jsonb),
  ('d43b3847-14d9-508a-8445-df7338ba1a66'::uuid, 2, 2, 10, 35, 3,
   $ex${"titre":"La Dette","competence":"analyser-texte","situation":"Voici le début d’une comédie écrite pour l’exercice, et l’affiche qui résume toute la pièce.","documents":[{"id":"dette","type":"texte","genre":"theatre","titre":"Acte I, scène 1","blocs":[{"didascalie":"Un salon aux meubles couverts de draps. Marthe ferme une fenêtre ; Paul lit le journal."},{"personnage":"Marthe","replique":"Comme tu le sais, Paul, depuis la mort de papa nous n’avons plus un sou."},{"personnage":"Paul","replique":"Oui, Marthe, je sais : la maison sera vendue avant l’été."}],"source":"Texte écrit pour l’exercice"},{"id":"affiche","type":"fiche","modele":"affiche","entete":"La Dette","sousTitre":"Comédie en quatre moments","emoji":"🎭","teinte":"ambre","lignes":[{"texte":"Acte I","valeur":"Marthe et Paul apprennent que la maison sera vendue.","id":"z1"},{"texte":"Acte II","valeur":"Paul se déguise en oncle d’Amérique pour tromper le notaire.","id":"z2"},{"texte":"Acte III","valeur":"Le notaire révèle qu’il est leur véritable oncle.","id":"z3"},{"texte":"Dernière scène","valeur":"La famille garde la maison et rit de l’affaire.","id":"z4"}],"pied":"Théâtre du Lycée"}],"questions":[{"enonce":"Touche **le verbe** qui montre que Marthe rappelle à Paul ce qu’il connaît déjà.","aide":"Cherche l’expression « comme tu le… ».","type":"zone","document":"dette","multiple":false},{"enonce":"Pourquoi Marthe rappelle-t-elle à Paul ce qu’il sait déjà ?","aide":"À qui cette réplique s’adresse-t-elle aussi ?","type":"choix","options":[{"id":"a","texte":"Pour changer de scène en faisant sortir un personnage"},{"id":"b","texte":"Pour se moquer de Paul devant tous les autres personnages"},{"id":"c","texte":"Pour annoncer à Paul une nouvelle qu’il ignore encore"},{"id":"d","texte":"Pour informer le spectateur, qui ne connaît pas la situation"}],"multiple":false},{"enonce":"Relie chaque moment de l’affiche à son rôle dans la pièce.","aide":"L’exposition pose la situation ; le dénouement la résout.","type":"association","gauche":[{"id":"g0","texte":"Acte I"},{"id":"g1","texte":"Acte II"},{"id":"g2","texte":"Acte III"},{"id":"g3","texte":"Dernière scène"}],"droite":[{"id":"d0","texte":"Les péripéties"},{"id":"d1","texte":"L’exposition"},{"id":"d2","texte":"Le dénouement"},{"id":"d3","texte":"Le coup de théâtre"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m18"]},"explication":"Marthe dit « comme tu le **sais** » : Paul connaît déjà l’information."},{"cle":{"type":"choix","ids":["d"]},"explication":"C’est la **double énonciation** : Marthe parle à Paul et, en même temps, au spectateur."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g3":"d2","g2":"d3"}},"explication":"Acte I : on pose la situation. Acte II : un rebondissement. Acte III : un renversement brutal. Dernière scène : la résolution."}]$ex$::jsonb),
  ('d43b3847-14d9-508a-8445-df7338ba1a66'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Monsieur Gratin, pharmacien","competence":"analyser-texte","situation":"Une scène comique écrite pour l’exercice, et la fiche de révision d’un élève sur les ressorts du comique.","documents":[{"id":"gratin","type":"texte","genre":"theatre","titre":"Scène 1","blocs":[{"didascalie":"Chez Monsieur Gratin, pharmacien. Il est seul et compte sa monnaie."},{"personnage":"Gratin","replique":"Un sou, deux sous, trois sous… Un centime de moins dans ce tiroir et je ne dormirai plus de la semaine."},{"didascalie":"Un client entre."},{"personnage":"Le client","replique":"Un sirop contre la toux, s’il vous plaît."},{"personnage":"Gratin","replique":"Dix euros."},{"personnage":"Le client","replique":"Dix ?"},{"personnage":"Gratin","replique":"Douze."},{"personnage":"Le client","replique":"Mais vous venez de le dire !"},{"personnage":"Gratin","replique":"Quinze, avec les remarques."}],"source":"Texte écrit pour l’exercice"},{"id":"ressorts","type":"tableau","titre":"Les ressorts du comique","colonnes":["Comique","Son ressort"],"lignes":[["De mots","Jeux de langage, répétitions"],["De gestes","Chutes, coups"],["De situation","Quiproquo, malentendu"],["De caractère","Le défaut poussé à l’extrême"]],"enteteLignes":true}],"questions":[{"enonce":"Que représente la première réplique de Gratin, avant l’arrivée du client ?","aide":"Gratin est seul sur scène : à qui parle-t-il ?","type":"choix","options":[{"id":"a","texte":"Une stichomythie"},{"id":"b","texte":"Un monologue"},{"id":"c","texte":"Un aparté"},{"id":"d","texte":"Une tirade adressée au client"}],"multiple":false},{"enonce":"Touche **les deux prix** que Gratin annonce après « Dix euros ».","aide":"Les prix montent à chaque réplique.","type":"zone","document":"gratin","multiple":true},{"enonce":"Comment appelle-t-on cet échange de répliques très brèves entre Gratin et son client ?","aide":"Regarde la longueur des répliques.","type":"choix","options":[{"id":"a","texte":"Une tirade"},{"id":"b","texte":"Un dénouement"},{"id":"c","texte":"Une stichomythie"},{"id":"d","texte":"Un monologue"}],"multiple":false},{"enonce":"Dans le tableau, touche **le ressort** qui explique le comique d’un pharmacien avare jusqu’à l’absurde.","aide":"Gratin a un défaut poussé très loin : lequel ?","type":"zone","document":"ressorts","multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["b"]},"explication":"Seul sur scène, il parle à voix haute : c’est un **monologue**."},{"cle":{"type":"zone","ids":["m47","m54"]},"explication":"Gratin annonce **Douze** puis **Quinze** : le prix grimpe sans raison."},{"cle":{"type":"choix","ids":["c"]},"explication":"Des répliques très brèves qui se répondent : une **stichomythie**."},{"cle":{"type":"zone","ids":["r3c1"]},"explication":"L’avarice de Gratin est **un défaut poussé à l’extrême** : c’est le comique de caractère."}]$ex$::jsonb),
  ('56657235-7e06-5636-99ff-e8e2c88853db'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Une lettre depuis l’Exposition","competence":"analyser-texte","situation":"Jeanne visite une grande Exposition universelle et écrit à sa cousine. Sa lettre est remplie de mots qui disent son enthousiasme.","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"Lettre de Jeanne","blocs":["Chère cousine,","Ce soir, l’Exposition est illuminée : des milliers d’ampoules brillent, les palais étincellent et toute la foule marche dans une clarté de rêve.","On m’a parlé du télégraphe qui porte une nouvelle en une minute, du vaccin qui sauve les enfants et de la photographie qui garde nos visages. Demain sera meilleur qu’aujourd’hui, j’en suis sûre !"],"source":"Lettre imaginée pour l’exercice"}],"questions":[{"enonce":"Touche les **quatre mots** du champ lexical de la lumière.","aide":"Cherche ce qui éclaire, brille, étincelle.","type":"zone","document":"lettre","multiple":true},{"enonce":"Touche les **trois inventions** du XIXe siècle citées par Jeanne.","aide":"Elles sont dans le dernier paragraphe : une pour les nouvelles, une contre la maladie, une pour les images.","type":"zone","document":"lettre","multiple":true},{"enonce":"Quel sentiment domine cette lettre ?","aide":"Relis la dernière phrase de Jeanne.","type":"choix","options":[{"id":"a","texte":"Un ennui de voyageuse"},{"id":"b","texte":"Une confiance joyeuse dans l’avenir"},{"id":"c","texte":"Une colère contre les inventeurs"},{"id":"d","texte":"Une peur devant les machines"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m7","m12","m15","m23"]},"explication":"Les mots de la lumière sont **illuminée, brillent, étincellent, clarté** : ils portent l’enthousiasme."},{"cle":{"type":"zone","ids":["m31","m40","m48"]},"explication":"Jeanne cite le **télégraphe, le vaccin et la photographie**."},{"cle":{"type":"choix","ids":["b"]},"explication":"Jeanne croit que « demain sera meilleur » : c’est **la confiance joyeuse dans le progrès** qu’exprime la littérature de l’exaltation."}]$ex$::jsonb),
  ('56657235-7e06-5636-99ff-e8e2c88853db'::uuid, 2, 2, 10, 35, 3,
   $ex${"titre":"Le sous-marin de l’Argonaute","competence":"analyser-texte","situation":"Voici un récit d’aventure écrit à la manière de Jules Verne. Regarde comment l’auteur te fait croire à sa machine… et à son héros.","documents":[{"id":"recit","type":"texte","genre":"recit","titre":"L’Argonaute plonge","blocs":["Le commandant Verdier, héros de cent traversées, posa la main sur la manette. Sous ses pieds, deux hélices mues par la pile électrique poussaient le sous-marin de soixante-dix mètres à douze nœuds.","Le manomètre indiquait déjà vingt atmosphères de pression : l’Argonaute descendait, géant d’acier, dompteur des abysses, vers un monde que nul n’avait vu."],"source":"Texte écrit pour l’exercice, dans l’esprit de Jules Verne"}],"questions":[{"enonce":"Touche les **trois mots techniques** qui décrivent la machine.","aide":"Cherche les instruments et les mesures, comme dans un manuel d’ingénieur.","type":"zone","document":"recit","multiple":true},{"enonce":"Touche le mot qui fait du commandant un personnage de légende.","aide":"Dans le premier paragraphe : un nom qu’on donne aux grands aventuriers.","type":"zone","document":"recit","multiple":false},{"enonce":"Relie chaque procédé à son effet.","aide":"Relis les procédés de l’exaltation dans ton cours.","type":"association","gauche":[{"id":"g0","texte":"Le vocabulaire technique"},{"id":"g1","texte":"Le registre épique"},{"id":"g2","texte":"L’hyperbole et l’énumération"},{"id":"g3","texte":"Le présent ou le futur"}],"droite":[{"id":"d0","texte":"Le marin devient héros, la machine un personnage"},{"id":"d1","texte":"Il garantit la vraisemblance"},{"id":"d2","texte":"Ils rendent l’avenir présent"},{"id":"d3","texte":"Elles saturent la page"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m17","m33","m39"]},"explication":"Les mots techniques sont **hélices, manomètre, pression** : ils donnent au récit un sérieux d’ingénieur."},{"cle":{"type":"zone","ids":["m3"]},"explication":"Le mot **héros** installe le registre épique : le marin devient un héros."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g3":"d2","g2":"d3"}},"explication":"Chaque procédé a son effet : le technique rend **crédible**, l’épique **héroïse**, l’hyperbole **sature**, le présent ou le futur **rapproche l’avenir**."}]$ex$::jsonb),
  ('56657235-7e06-5636-99ff-e8e2c88853db'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"La cité d’Héliopolis","competence":"analyser-texte","situation":"Un auteur décrit une ville imaginaire en l’an 2100. Mais que veut-il dire de sa propre époque ? Lis le texte, puis le tableau qui le complète.","documents":[{"id":"cite","type":"texte","genre":"recit","titre":"Héliopolis, an 2100","blocs":["Dans la cité d’Héliopolis, personne n’aura faim, car des machines cultiveront la terre. Les ouvriers ne porteront plus de fardeaux, et les hôpitaux soigneront gratuitement chaque malade.","Les enfants apprendront le matin ; l’après-midi, ils joueront sous des arcades de verre."],"source":"Texte écrit pour l’exercice"},{"id":"tab","type":"tableau","titre":"Ce que la cité imaginaire corrige","colonnes":["Dans Héliopolis","Dans la France de l’auteur (XIXe siècle)"],"lignes":[["Plus de faim","Des familles ouvrières mal nourries"],["Des machines portent les fardeaux","Un travail pénible qui use les corps"],["Soins gratuits pour tous","Des malades trop pauvres pour se soigner"]],"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Dans le premier paragraphe, touche les **trois verbes au futur** qui ont pour sujet « personne », « des machines » et « les ouvriers ».","aide":"Cherche les verbes qui disent ce qui arrivera plus tard.","type":"zone","document":"cite","multiple":true},{"enonce":"Relie chaque progrès de la cité à la misère qu’il critique.","aide":"Regarde la colonne de droite du tableau.","type":"association","gauche":[{"id":"g0","texte":"Les machines portent les fardeaux"},{"id":"g1","texte":"Personne n’a faim"},{"id":"g2","texte":"Les soins sont gratuits"}],"droite":[{"id":"d0","texte":"Le travail pénible des ouvriers"},{"id":"d1","texte":"Les malades sans argent"},{"id":"d2","texte":"La misère des familles mal nourries"}]},{"enonce":"Que cherche surtout l’auteur en décrivant cette cité parfaite ?","aide":"Que montre le tableau ? Ce que la cité corrige, dans la France de l’auteur.","type":"choix","options":[{"id":"a","texte":"Faire voir ce que son époque pourrait devenir et lui reprocher ses injustices"},{"id":"b","texte":"Décrire une ville réelle qu’il a visitée et dont il fait un guide touristique"},{"id":"c","texte":"Prédire exactement la vie des hommes en 2100, année par année et sans erreur"},{"id":"d","texte":"Vendre des machines aux lecteurs en leur vantant les progrès de l’industrie"}],"multiple":false},{"enonce":"Complète la définition de l’utopie.","aide":"Regarde les mots de ton cours : société idéale, raison, technique.","type":"trous","segments":["Une utopie décrit une société ",0," rendue possible par la ",1," et la ",2,"."],"banque":["idéale","technique","magie","guerre","raison"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m6","m7","m12","m18"]},"explication":"Les verbes **n’aura, cultiveront, porteront** sont au futur : l’auteur rend l’avenir présent, comme s’il était déjà là."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g1":"d2"}},"explication":"Chaque merveille de la cité répond à un **défaut réel** du XIXe siècle : l’utopie critique le présent."},{"cle":{"type":"choix","ids":["a"]},"explication":"L’utopie sert moins à prédire qu’à **critiquer le présent** en montrant ce qu’il pourrait être."},{"cle":{"type":"trous","trous":[["ideale","parfaite"],["raison"],["technique","science"]]},"affichage":"idéale · raison · technique","explication":"Une utopie décrit une société **idéale** rendue possible par la **raison** et la **technique**."}]$ex$::jsonb),
  ('ac2c6f3e-a75f-539a-b0ce-460cbee9aaca'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"La nuit où la créature s’éveilla","competence":"analyser-texte","situation":"Voici un résumé écrit pour l’exercice, inspiré du roman *Frankenstein*. Il raconte ce que fait un savant de sa découverte.","documents":[{"id":"nuit","type":"texte","genre":"recit","titre":"Dans le laboratoire","blocs":["Par une nuit d’orage, le jeune Victor acheva sa machine. Quand la créature ouvrit les yeux, il ne ressentit pas de joie, mais de l’horreur.","Il s’enfuit et la laissa seule dans le noir. Personne ne lui apprit à parler, personne ne lui tendit la main : rejetée par tous, elle devint violente."],"source":"Résumé écrit pour l’exercice, d’après le roman de Mary Shelley (1818)"}],"questions":[{"enonce":"Touche le mot qui dit ce que ressent Victor devant sa créature.","aide":"Il attendait de la joie… mais le texte dit un autre sentiment.","type":"zone","document":"nuit","multiple":false},{"enonce":"Touche les **deux mots** qui disent que la créature est abandonnée.","aide":"Cherche dans le second paragraphe.","type":"zone","document":"nuit","multiple":true},{"enonce":"Qui est responsable du drame dans ce résumé ?","aide":"Qui s’enfuit ? Qui laisse l’autre seul ?","type":"choix","options":[{"id":"a","texte":"La créature, mauvaise dès sa naissance"},{"id":"b","texte":"Les voisins de Victor"},{"id":"c","texte":"Le savant, qui abandonne ce qu’il a créé"},{"id":"d","texte":"L’orage qui frappe le laboratoire"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m26"]},"explication":"Victor ressent de l’**horreur** : il rejette ce qu’il a créé."},{"cle":{"type":"zone","ids":["m33","m49"]},"explication":"La créature est **seule** et **rejetée** : c’est l’abandon qui la rend violente."},{"cle":{"type":"choix","ids":["c"]},"explication":"Le monstre n’est pas mauvais par nature : il le devient parce que **Victor l’abandonne**."}]$ex$::jsonb),
  ('ac2c6f3e-a75f-539a-b0ce-460cbee9aaca'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Trois mondes trop parfaits","competence":"analyser-document","situation":"Une bibliothécaire présente trois romans dans un tableau. Ce sont trois sociétés parfaitement organisées… et invivables.","documents":[{"id":"tab","type":"tableau","titre":"Trois contre-utopies","colonnes":["Œuvre (auteur)","Année","Un détail du monde imaginé"],"lignes":[["*Le Meilleur des mondes* (Huxley)",1932,"Les enfants sont conditionnés pour aimer leur condition"],["*1984* (Orwell)",1949,"Un écran surveille chaque foyer"],["*Fahrenheit 451* (Bradbury)",1953,"Des pompiers brûlent les livres"]],"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche la case qui décrit le monde où l’on brûle les livres.","aide":"Cherche dans la dernière colonne le métier des pompiers.","type":"zone","document":"tab","multiple":false},{"enonce":"Combien d’années séparent la parution du *Meilleur des mondes* de celle de *Fahrenheit 451* ?","aide":"Soustrais les deux dates de la colonne « Année ».","type":"nombre","unite":"ans"},{"enonce":"Relie chaque œuvre à ce que son monde supprime.","aide":"Un détail de la dernière colonne peut t’aider.","type":"association","gauche":[{"id":"g0","texte":"*Le Meilleur des mondes*"},{"id":"g1","texte":"*1984*"},{"id":"g2","texte":"*Fahrenheit 451*"}],"droite":[{"id":"d0","texte":"Les livres"},{"id":"d1","texte":"La révolte, par la surveillance"},{"id":"d2","texte":"La liberté"}]},{"enonce":"Pourquoi appelle-t-on ces romans des contre-utopies ?","aide":"Le mot « contre » : l’inverse d’une société idéale.","type":"choix","options":[{"id":"a","texte":"Ils racontent l’histoire vraie d’un savant et de ses découvertes"},{"id":"b","texte":"Ils refusent toute forme de science et de technique moderne"},{"id":"c","texte":"Ils décrivent une société idéale et heureuse, sans aucun défaut"},{"id":"d","texte":"Ils décrivent une société parfaitement organisée, mais invivable"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r2c2"]},"explication":"Dans *Fahrenheit 451*, **les pompiers brûlent les livres** : c’est la case de la troisième ligne."},{"cle":{"type":"nombre","valeur":21,"tolerance":0},"affichage":"21 ans","explication":"1953 − 1932 = **21 ans**."},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g0":"d2"}},"explication":"Le monde de Huxley supprime la **liberté**, celui d’Orwell la **révolte**, celui de Bradbury les **livres**."},{"cle":{"type":"choix","ids":["d"]},"explication":"Ce sont des **sociétés parfaitement organisées… et invivables**, qui montrent le prix de cette perfection."}]$ex$::jsonb),
  ('ac2c6f3e-a75f-539a-b0ce-460cbee9aaca'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Le sérum du professeur Halden","competence":"analyser-texte","situation":"Un récit d’inquiétude écrit pour l’exercice, puis un extrait d’éditorial imaginaire d’aujourd’hui : les deux parlent de la même question.","documents":[{"id":"halden","type":"texte","genre":"recit","titre":"Le sérum","blocs":["Le professeur Halden s’enferma trois nuits dans son laboratoire, dans le froid d’une cave sans fenêtre. Quand il sortit, son sérum contre la vieillesse était prêt.","Le mal était déjà fait : le sérum empoisonnait l’eau du village, et Halden, penché sur ses fioles, ne savait plus comment l’arrêter. Dans la nuit noire, verrouillée de peurs, les villageois fuyaient."],"source":"Texte écrit pour l’exercice"},{"id":"edito","type":"texte","genre":"article","titre":"Éditorial, 2030","blocs":["Une entreprise annonce un assistant capable d’écrire et de décider à notre place. Qui en contrôlera l’usage ? Pour quoi sera-t-il utilisé ? Et à quel prix pour nos libertés ?"],"source":"Éditorial imaginaire, écrit pour l’exercice"}],"questions":[{"enonce":"Touche les **trois mots** qui créent une atmosphère oppressante dans le récit.","aide":"Cherche ce qui glace, empoisonne, enferme.","type":"zone","document":"halden","multiple":true},{"enonce":"Quel événement du récit est un retournement ?","aide":"Une invention qui se retourne contre ceux qu’elle devait protéger.","type":"choix","options":[{"id":"a","texte":"Le village est bâti au bord d’une rivière, en pleine vallée"},{"id":"b","texte":"Halden passe trois nuits à préparer son sérum"},{"id":"c","texte":"Le sérum contre la vieillesse empoisonne le village"},{"id":"d","texte":"Les villageois dorment profondément pendant la nuit"}],"multiple":false},{"enonce":"Quelle figure Halden incarne-t-il ?","aide":"Halden « ne savait plus comment l’arrêter » : à quelle figure cela ressemble-t-il ?","type":"choix","options":[{"id":"a","texte":"L’apprenti sorcier, qui déclenche ce qu’il ne sait plus arrêter"},{"id":"b","texte":"Le héros épique, qui triomphe de la nature par son courage"},{"id":"c","texte":"Le sage, qui refuse toute invention pour protéger les autres"},{"id":"d","texte":"Le savant fou, qui agit sans la moindre conscience du danger"}],"multiple":false},{"enonce":"Quelle question de Shelley, Huxley ou Orwell l’éditorial reprend-il ?","aide":"Relis les trois questions posées à la fin de l’éditorial.","type":"choix","options":[{"id":"a","texte":"Comment construire plus vite des machines plus puissantes"},{"id":"b","texte":"Quelle invention a été faite en premier dans l’histoire"},{"id":"c","texte":"Qui contrôle la science, pour quoi faire et à quel prix"},{"id":"d","texte":"Pourquoi la science ennuie autant les élèves à l’école"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m12","m35","m56"]},"explication":"**Froid, empoisonnait, verrouillée** installent l’inquiétude : le champ lexical de l’oppression."},{"cle":{"type":"choix","ids":["c"]},"explication":"Le **retournement** : l’invention se retourne contre son inventeur et contre ceux qu’elle devait sauver."},{"cle":{"type":"choix","ids":["a"]},"explication":"Halden déclenche un processus qu’il ne sait plus arrêter : c’est **l’apprenti sorcier**."},{"cle":{"type":"choix","ids":["c"]},"explication":"Les trois questions **qui contrôle, pour quoi, à quel prix** n’ont pas vieilli : c’est la question ouverte de la science."}]$ex$::jsonb),
  ('b95a3e44-9425-5f3c-88f9-27e25d5ee3fb'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"La ville s’éveille","competence":"analyser-texte","situation":"Voici un petit poème écrit pour l’exercice. Le poète y regarde un matin de brouillard.","documents":[{"id":"poeme","type":"texte","genre":"poeme","titre":"Matin de brouillard","blocs":["Ce matin, la ville s’éveille","Dans un brouillard couleur de lait ;","Les toits fument, le jour sommeille","Et le silence se défait.","","Un tramway passe en grelottant,","Sa vitre est pleine de visages ;","Mon regard les suit un instant,","Comme des barques sur les nuages."],"source":"Poème écrit pour l’exercice"}],"questions":[{"enonce":"Dans la première strophe, touche le mot qui **rime avec « lait »**.","aide":"Cherche à la fin d’un autre vers de la strophe.","type":"zone","document":"poeme","multiple":false,"portee":[0,1,2,3]},{"enonce":"Dans la première strophe, touche les **deux verbes** qui prêtent à la ville et au jour des gestes humains.","aide":"On dit d’habitude qu’un être humain s’éveille ou sommeille.","type":"zone","document":"poeme","multiple":true,"portee":[0,1,2,3]},{"enonce":"Dans la seconde strophe, touche le petit mot qui annonce une comparaison.","aide":"C’est un mot très court, qui relie deux réalités.","type":"zone","document":"poeme","multiple":false,"portee":[5,6,7,8]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m22"]},"explication":"Le mot **défait** rime avec « lait » : c’est la rime du deuxième et du quatrième vers."},{"cle":{"type":"zone","ids":["m4","m5","m17"]},"explication":"**S’éveille** et **sommeille** : la ville et le jour sont personnifiés."},{"cle":{"type":"zone","ids":["m40"]},"explication":"Le mot **comme** introduit la comparaison : les visages sont rapprochés de barques qui flottent."}]$ex$::jsonb),
  ('b95a3e44-9425-5f3c-88f9-27e25d5ee3fb'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Sous les néons de la ville","competence":"lire-tableau","situation":"Une poétesse imagine la ville la nuit, avec des vers libres. À toi de lire ce qu’elle regarde.","documents":[{"id":"ville","type":"texte","genre":"poeme","titre":"Nuit en ville","blocs":["Les vitrines allument la nuit","comme des lanternes de fête.","Dans le métro, cent visages","sans nom","glissent côte à côte","et personne ne se regarde.","","Moi, je les compte","comme on compte les étoiles."],"source":"Poème écrit pour l’exercice"}],"questions":[{"enonce":"Touche les **deux mots** qui montrent la ville moderne.","aide":"Un lieu où on regarde des objets à vendre, un lieu où on prend la ligne.","type":"zone","document":"ville","multiple":true},{"enonce":"Quel sentiment le poème fait-il ressentir ?","aide":"Regarde les vers 3 à 6 : les visages se croisent, mais…","type":"choix","options":[{"id":"a","texte":"La peur d’un danger"},{"id":"b","texte":"La solitude au milieu de la foule"},{"id":"c","texte":"La joie d’une fête entre amis"},{"id":"d","texte":"L’admiration pour un paysage de montagne"}],"multiple":false},{"enonce":"Relie chaque thème poétique à ses auteurs.","aide":"Relis les thèmes du regard poétique dans ton cours.","type":"association","gauche":[{"id":"g0","texte":"La nature et les saisons"},{"id":"g1","texte":"La ville moderne"},{"id":"g2","texte":"Les objets humbles du quotidien"},{"id":"g3","texte":"Le temps qui passe"}],"droite":[{"id":"d0","texte":"Ponge"},{"id":"d1","texte":"Apollinaire, Cendrars"},{"id":"d2","texte":"Lamartine, Hugo"},{"id":"d3","texte":"Ronsard, Apollinaire"}]},{"enonce":"Pourquoi ce poème est-il écrit en vers libres ?","aide":"Compare la longueur des vers : sont-ils tous pareils ?","type":"choix","options":[{"id":"a","texte":"Il n’a ni rime ni mètre réguliers : le rythme de la phrase fait le poème"},{"id":"b","texte":"Il est écrit sans aucun retour à la ligne, comme un texte en prose continue"},{"id":"c","texte":"Il suit exactement la forme d’un sonnet, avec deux quatrains et deux tercets"},{"id":"d","texte":"Il ne contient que des alexandrins, avec des rimes suivies et un rythme fixe"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m1","m12"]},"explication":"**Vitrines** et **métro** appartiennent à la ville moderne, avec ses foules et ses devantures."},{"cle":{"type":"choix","ids":["b"]},"explication":"**« Cent visages sans nom »** et « personne ne se regarde » : le poème dit la solitude dans la foule."},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g0":"d2","g3":"d3"}},"explication":"Chaque thème a ses poètes : nature → Lamartine et Hugo, ville → Apollinaire et Cendrars, objets → Ponge, temps → Ronsard."},{"cle":{"type":"choix","ids":["a"]},"explication":"Les vers n’ont ni **rime** ni **mètre** réguliers : c’est le **vers libre**."}]$ex$::jsonb),
  ('b95a3e44-9425-5f3c-88f9-27e25d5ee3fb'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Lire un poème comme un trajet","competence":"analyser-texte","situation":"On te donne un quatrain écrit pour l’exercice. Lis-le comme le demande ton cours : forme, images, sonorités, mouvement.","documents":[{"id":"soir","type":"texte","genre":"poeme","titre":"Le soir sur la mer","blocs":["Le soleil s’en va, sans un bruit ;","Le soir sème du sel sur la mer ;","Et mon cœur, seul comme la nuit,","Écoute le temps qui s’enfuit."],"source":"Poème écrit pour l’exercice"}],"questions":[{"enonce":"Dans le deuxième vers, touche les **quatre mots** qui commencent par la consonne « s ».","aide":"Une même consonne revient : c’est un son qui ressemble à un souffle.","type":"zone","document":"soir","multiple":true,"portee":[1]},{"enonce":"Touche le petit mot qui introduit la comparaison du troisième vers.","aide":"C’est le même mot que dans la phrase « fort comme un chêne ».","type":"zone","document":"soir","multiple":false},{"enonce":"À quel moment le poème passe-t-il de la nature à l’état d’âme ?","aide":"Dans les deux premiers vers, que décrit-on ? Puis que décrit-on ?","type":"choix","options":[{"id":"a","texte":"Au deuxième vers, avec « mer »"},{"id":"b","texte":"Au troisième vers, avec « mon cœur »"},{"id":"c","texte":"Au premier vers, avec « soleil »"},{"id":"d","texte":"Il ne passe jamais de l’un à l’autre"}],"multiple":false},{"enonce":"Remets dans l’ordre les étapes pour lire un poème.","aide":"Commence par ce qu’on voit sur la page.","type":"ordre","items":[{"id":"a","texte":"Le mouvement : d’où part le texte, où arrive-t-il ?"},{"id":"b","texte":"Les images : comparaisons et métaphores"},{"id":"c","texte":"Les sonorités : allitérations et assonances"},{"id":"d","texte":"La forme : les vers, les strophes, les rimes"}]},{"enonce":"Complète la conclusion de la lecture.","aide":"La nature renvoie les sentiments du poète, comme une glace.","type":"trous","segments":["Dans ce poème, la nature est le ",0," des états d’âme du poète : c’est du ",1,"."],"banque":["lyrisme","décor","satire","miroir"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m9","m10","m12","m13"]},"explication":"**Soir, sème, sel, sur** commencent par [s] : c’est une allitération qui fait entendre la mer et le sable."},{"cle":{"type":"zone","ids":["m20"]},"explication":"**Comme** lie le cœur du poète à la nuit : « seul comme la nuit »."},{"cle":{"type":"choix","ids":["b"]},"explication":"Après deux vers sur le **paysage**, le troisième parle du **cœur** : c’est le mouvement du poème, du dehors au dedans."},{"cle":{"type":"ordre","ids":["d","b","c","a"]},"explication":"On lit d’abord la **forme**, puis les **images**, les **sonorités**, enfin le **mouvement** : un poème est un trajet."},{"cle":{"type":"trous","trous":[["miroir","reflet"],["lyrisme"]]},"affichage":"miroir · lyrisme","explication":"La nature est le **miroir** des états d’âme : c’est du **lyrisme**."}]$ex$::jsonb),
  ('d1604e54-ac06-5ea5-b640-b367c3566254'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le lac et la lune","competence":"analyser-texte","situation":"Voici un petit poème écrit pour l’exercice : le poète transforme un paysage avec trois figures de style.","documents":[{"id":"lac","type":"texte","genre":"poeme","titre":"Soir au bord du lac","blocs":["Le vent gémit dans la forêt,","Le lac est un miroir d’argent,","La lune, comme une pièce d’or,","Éclaire le soir qui descend."],"source":"Poème écrit pour l’exercice"}],"questions":[{"enonce":"Touche le verbe qui prête au vent un cri humain.","aide":"On dit d’une personne qu’elle gémit, pas d’un courant d’air.","type":"zone","document":"lac","multiple":false},{"enonce":"Touche le petit mot qui signale la comparaison entre la lune et une pièce d’or.","aide":"C’est l’outil qui relie les deux réalités.","type":"zone","document":"lac","multiple":false},{"enonce":"Que fait voir la métaphore « le lac est un miroir d’argent » ?","aide":"À quoi sert un miroir ? De quelle couleur est l’argent ?","type":"choix","options":[{"id":"a","texte":"Que le poète habite dans une maison au bord du lac"},{"id":"b","texte":"Que le lac est lisse, brillant et qu’il reflète le ciel"},{"id":"c","texte":"Que le lac est vraiment fait de métal, comme un miroir"},{"id":"d","texte":"Que le lac est dangereux, sombre et très profond au centre"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m2"]},"explication":"Le verbe **gémit** personnifie le vent : il prend un cri humain."},{"cle":{"type":"zone","ids":["m15"]},"explication":"Le mot **comme** est l’outil de la comparaison : la lune est rapprochée d’une pièce d’or."},{"cle":{"type":"choix","ids":["b"]},"explication":"La métaphore fait voir un lac **lisse, brillant, qui renvoie le ciel** : on garde ce que les deux réalités ont en commun."}]$ex$::jsonb),
  ('d1604e54-ac06-5ea5-b640-b367c3566254'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Quatre vers pour l’oreille","competence":"analyser-texte","situation":"Un poète s’amuse à jouer avec les sons. Lis ses quatre vers à voix haute dans ta tête, puis trie ce que tu entends.","documents":[{"id":"sons","type":"texte","genre":"poeme","titre":"Quatre vers pour l’oreille","blocs":["Le pas pressé du petit poney","Un gros chat gris grogne","Le vent lent chantant dans les champs","Le long son profond du bourdon"],"source":"Vers écrits pour l’exercice"}],"questions":[{"enonce":"Dans le premier vers, touche les **quatre mots** qui commencent par la consonne « p ».","aide":"Écoute la consonne qui éclate au début de plusieurs mots.","type":"zone","document":"sons","multiple":true,"portee":[0]},{"enonce":"Dans le dernier vers, touche les **quatre mots** où l’on entend la même voyelle nasale [ɔ̃].","aide":"La voyelle de « long » se retrouve dans trois autres mots.","type":"zone","document":"sons","multiple":true,"portee":[3]},{"enonce":"Classe chaque vers selon le son qui se répète.","aide":"Une consonne qui revient, ou une voyelle qui revient ?","type":"categories","categories":[{"id":"c0","texte":"Allitération (consonne)"},{"id":"c1","texte":"Assonance (voyelle)"}],"items":[{"id":"i0","texte":"Le long son profond du bourdon"},{"id":"i1","texte":"Le vent lent chantant dans les champs"},{"id":"i2","texte":"Le pas pressé du petit poney"},{"id":"i3","texte":"Un gros chat gris grogne"}]},{"enonce":"Que produit la répétition des sons dans ces vers ?","aide":"Un poème se lit à voix haute : l’oreille entend avant l’œil.","type":"choix","options":[{"id":"a","texte":"Une musique qui s’ajoute au sens"},{"id":"b","texte":"Une explication plus précise"},{"id":"c","texte":"Un changement de sujet"},{"id":"d","texte":"Une rime obligatoire"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m1","m2","m4","m5"]},"explication":"**Pas, pressé, petit, poney** : la consonne [p] revient quatre fois, c’est une allitération."},{"cle":{"type":"zone","ids":["m19","m20","m21","m23"]},"explication":"**Long, son, profond, bourdon** : la voyelle [ɔ̃] revient quatre fois, c’est une assonance."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c0"}},"explication":"Dans les vers 1 et 2, une **consonne** se répète ([p], [gr]) : allitération. Dans les vers 3 et 4, une **voyelle** ([ɑ̃], [ɔ̃]) : assonance."},{"cle":{"type":"choix","ids":["a"]},"explication":"Le poème **fait entendre** ce qu’il décrit : les sons répétés créent une musique qui s’ajoute au sens."}]$ex$::jsonb),
  ('d1604e54-ac06-5ea5-b640-b367c3566254'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Quand la nuit devient mer","competence":"analyser-document","situation":"Deux documents : un poème inventé dans l’esprit des surréalistes, puis les réponses de quatre élèves à un sujet d’écriture. Tu vas repérer les figures.","documents":[{"id":"nuitmer","type":"texte","genre":"poeme","titre":"La nuit est une mer","blocs":["La nuit est une mer retournée","Où les étoiles, comme des poissons d’argent,","Frétillent quand le vent les appelle","Et se laissent glisser vers le toit du monde."],"source":"Poème écrit pour l’exercice"},{"id":"eleves","type":"texte","genre":"consigne","titre":"Quatre réponses d’élèves","blocs":["Sujet : transformer un objet de sa chambre en autre chose, en une seule phrase.","Inès : « Mon réveil est un coq de plastique. »","Malo : « Mon réveil sonne comme un coq. »","Jade : « Mon réveil sonne à sept heures. »","Noé : « Mon réveil hurle de fatigue. »"],"source":"Réponses écrites pour l’exercice"}],"questions":[{"enonce":"Dans le premier vers, touche les **deux réalités** que le poète rapproche.","aide":"Un moment de la journée et une étendue d’eau salée.","type":"zone","document":"nuitmer","multiple":true},{"enonce":"Que fait voir ce rapprochement ?","aide":"Une mer est profonde et remue ; des poissons d’argent brillent dedans.","type":"choix","options":[{"id":"a","texte":"Un voyage en bateau réel que le poète a vraiment fait"},{"id":"b","texte":"Une tempête violente qui détruit tout sur son passage"},{"id":"c","texte":"Une nuit sans étoiles, noire, immobile et silencieuse"},{"id":"d","texte":"Une nuit profonde, mouvante, pleine de points qui brillent"}],"multiple":false},{"enonce":"Relie chaque groupe de mots du poème à sa figure.","aide":"Cherche d’abord le mot « comme », puis ce qu’un humain seul peut faire.","type":"association","gauche":[{"id":"g0","texte":"« La nuit est une mer retournée »"},{"id":"g1","texte":"« les étoiles, comme des poissons d’argent »"},{"id":"g2","texte":"« le vent les appelle »"}],"droite":[{"id":"d0","texte":"Personnification : le vent agit comme un être humain"},{"id":"d1","texte":"Métaphore : pas d’outil de comparaison"},{"id":"d2","texte":"Comparaison : l’outil « comme »"}]},{"enonce":"Laquelle de ces phrases d’élèves contient une métaphore ?","aide":"Une métaphore supprime l’outil de comparaison : « est » relie directement les deux réalités.","type":"choix","options":[{"id":"a","texte":"« Mon réveil est un coq de plastique. »"},{"id":"b","texte":"« Mon réveil hurle de fatigue. »"},{"id":"c","texte":"« Mon réveil sonne comme un coq. »"},{"id":"d","texte":"« Mon réveil sonne à sept heures. »"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m1","m4"]},"explication":"Le poète rapproche la **nuit** et la **mer** : c’est le mécanisme de la métaphore."},{"cle":{"type":"choix","ids":["d"]},"explication":"Le rapprochement fait voir une **nuit profonde, mouvante, parsemée de lueurs** : une connaissance que la phrase littérale ne donnait pas."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g1":"d2"}},"explication":"La nuit **est** une mer : métaphore. Les étoiles sont **comme** des poissons : comparaison. Le vent **appelle** : personnification."},{"cle":{"type":"choix","ids":["a"]},"explication":"La phrase d’**Inès** est une métaphore : l’outil « comme » a disparu. Malo fait une comparaison, Jade décrit sans figure, Noé personnifie."}]$ex$::jsonb),
  ('258f7c2b-56fe-5aae-8e30-33ac35f44de1'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Je me présente","competence":"analyser-texte","situation":"Nour s’est décrite elle-même pour le journal du collège. Regarde ce qu’elle dit de son corps et de son caractère.","documents":[{"id":"nour","type":"texte","genre":"recit","titre":"Autoportrait de Nour","blocs":["Je m’appelle Nour. J’ai les cheveux noirs, toujours en bataille, et de grands yeux que ma grand-mère dit « curieux ».","Je suis rêveuse, parfois têtue ; j’aime le football et je déteste me lever tôt."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche les **deux mots** du portrait physique.","aide":"Cherche ce qu’on voit sur le visage de Nour.","type":"zone","document":"nour","multiple":true},{"enonce":"Touche les **deux mots** du portrait moral.","aide":"Cherche dans la seconde phrase : des mots de caractère.","type":"zone","document":"nour","multiple":true},{"enonce":"À quelle personne et à quel temps Nour s’est-elle décrite ?","aide":"Regarde « Je m’appelle », « J’ai », « Je suis ».","type":"choix","options":[{"id":"a","texte":"À la première personne, au plus-que-parfait"},{"id":"b","texte":"À la deuxième personne, au futur"},{"id":"c","texte":"À la troisième personne, au passé simple"},{"id":"d","texte":"À la première personne, au présent"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m7","m15"]},"explication":"Le portrait physique tient dans **cheveux** et **yeux** : Nour décrit son corps."},{"cle":{"type":"zone","ids":["m23","m25"]},"explication":"**Rêveuse** et **têtue** font le portrait moral : Nour décrit son caractère."},{"cle":{"type":"choix","ids":["d"]},"explication":"**Je** (première personne) et le **présent** : Nour se montre telle qu’elle est maintenant."}]$ex$::jsonb),
  ('258f7c2b-56fe-5aae-8e30-33ac35f44de1'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Raconter ou se peindre ?","competence":"analyser-texte","situation":"Deux extraits écrits pour l’exercice, par deux auteurs qui parlent d’eux-mêmes. Mais ne font-ils pas la même chose ?","documents":[{"id":"a","type":"texte","genre":"recit","titre":"Extrait 1","blocs":["En 1998, j’ai quitté Lyon pour Nantes. L’année suivante, j’ai trouvé du travail dans une librairie, puis j’ai rencontré Claire, que j’ai épousée en 2003."],"source":"Texte écrit pour l’exercice"},{"id":"b","type":"texte","genre":"recit","titre":"Extrait 2","blocs":["Je suis un homme distrait, têtu, fidèle en amitié. J’aime le café noir et le silence du matin ; j’ai horreur du bruit. Je me crois généreux, mais je suis avare de mon temps."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Dans l’extrait 1, touche les **deux dates** qui ancrent le récit dans le temps.","aide":"Ce sont deux nombres à quatre chiffres.","type":"zone","document":"a","multiple":true},{"enonce":"Lequel des deux extraits est le début d’une autobiographie ?","aide":"Une autobiographie raconte ; un autoportrait décrit.","type":"choix","options":[{"id":"a","texte":"Les deux, car ils disent « je » et parlent du passé"},{"id":"b","texte":"L’extrait 1 : il raconte des événements dans l’ordre du temps"},{"id":"c","texte":"Aucun des deux, car ni l’un ni l’autre ne raconte une vie"},{"id":"d","texte":"L’extrait 2 : il parle surtout d’amitié et de sentiments"}],"multiple":false},{"enonce":"Dans l’extrait 2, touche les **trois défauts** que l’auteur s’attribue.","aide":"Un autoportrait honnête n’est pas un éloge : cherche ce qui n’est pas flatteur.","type":"zone","document":"b","multiple":true},{"enonce":"Relie chaque genre à sa forme et à sa question.","aide":"L’un suit le fil du temps, l’autre s’arrête pour décrire.","type":"association","gauche":[{"id":"g0","texte":"L’autobiographie"},{"id":"g1","texte":"L’autoportrait"}],"droite":[{"id":"d0","texte":"Un tableau : « Qui suis-je ? »"},{"id":"d1","texte":"Un récit : « Qu’est-ce qui m’est arrivé ? »"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m1","m29"]},"explication":"Les dates **1998** et **2003** montrent que l’auteur raconte sa vie dans le fil du temps."},{"cle":{"type":"choix","ids":["b"]},"explication":"L’extrait 1 **raconte** une vie dans le fil du temps : c’est de l’autobiographie."},{"cle":{"type":"zone","ids":["m4","m5","m31"]},"explication":"**Distrait, têtu, avare** : l’auteur avoue des défauts, c’est ce qui rend son autoportrait honnête."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1"}},"explication":"L’autobiographie est un **récit** qui répond à « qu’est-ce qui m’est arrivé ? » ; l’autoportrait est un **tableau** qui répond à « qui suis-je ? »."}]$ex$::jsonb),
  ('258f7c2b-56fe-5aae-8e30-33ac35f44de1'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Le miroir est-il fidèle ?","competence":"analyser-document","situation":"Un auteur se décrit sans indulgence, et une affiche présente trois peintres qui se sont représentés. Est-ce qu’on peut les croire sur parole ?","documents":[{"id":"aveu","type":"texte","genre":"recit","titre":"Un autoportrait sans indulgence","blocs":["Je suis, je l’avoue, d’une intelligence ordinaire, d’une laideur honnête et d’une paresse sans égale.","On me dit parfois généreux : c’est faux, je ne donne que ce dont je n’ai pas besoin."],"source":"Texte écrit pour l’exercice"},{"id":"affiche","type":"fiche","modele":"affiche","entete":"Se peindre soi-même","sousTitre":"Trois peintres, trois autoportraits","emoji":"🎨","lignes":[{"texte":"Rembrandt","valeur":"Plus de quatre-vingts autoportraits","id":"z1"},{"texte":"Van Gogh","valeur":"Il se peint l’oreille bandée","id":"z2"},{"texte":"Frida Kahlo","valeur":"Son corps blessé est le sujet même de l’œuvre","id":"z3"}],"pied":"Salle 4 — entrée libre","teinte":"violet"}],"questions":[{"enonce":"Dans l’autoportrait, touche les **trois mots** par lesquels l’auteur se noircit.","aide":"Cherche ce qui n’est pas flatteur : intelligence, physique, travail.","type":"zone","document":"aveu","multiple":true},{"enonce":"Pourquoi un auteur peut-il se noircir ainsi ?","aide":"Un autoportrait se lit comme une construction : que veut-il faire croire ?","type":"choix","options":[{"id":"a","texte":"Pour paraître honnête par sa modestie apparente"},{"id":"b","texte":"Parce qu’il est obligé de tout avouer"},{"id":"c","texte":"Pour changer de sujet"},{"id":"d","texte":"Parce qu’il ne connaît pas ses qualités"}],"multiple":false},{"enonce":"Sur l’affiche, touche la ligne du peintre dont le corps blessé est le sujet même de l’œuvre.","aide":"Relis la colonne de droite : un seul dit « corps blessé ».","type":"zone","document":"affiche","multiple":false},{"enonce":"Complète la conclusion.","aide":"Un miroir renvoie tout, une construction choisit.","type":"trous","segments":["Un autoportrait se lit comme une ",0,", pas comme un ",1," : ce que l’auteur veut faire croire de lui fait partie de son ",2,"."],"banque":["éloge","construction","miroir","portrait","récit"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m8","m11","m16"]},"explication":"**Ordinaire, laideur, paresse** : l’auteur se noircit."},{"cle":{"type":"choix","ids":["a"]},"explication":"Se **noircir par modestie** donne l’air honnête : ce que l’auteur veut faire croire de lui fait partie de son portrait."},{"cle":{"type":"zone","ids":["z3"]},"explication":"**Frida Kahlo** fait de son corps blessé le sujet de ses autoportraits."},{"cle":{"type":"trous","trous":[["construction"],["miroir"],["portrait"]]},"affichage":"construction · miroir · portrait","explication":"Un autoportrait est une **construction**, pas un **miroir** : ce qu’on veut faire croire fait partie du **portrait**."}]$ex$::jsonb),
  ('b126ab7d-8f1f-5918-908d-c1e552dd845d'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"La cour de grand-mère","competence":"analyser-texte","situation":"Un adulte raconte un souvenir d’enfance dans un passage écrit pour l’exercice. Deux voix s’y répondent.","documents":[{"id":"gm","type":"texte","genre":"recit","titre":"Chez grand-mère","blocs":["Chaque été, nous partions chez ma grand-mère. Un matin, j’ai cassé son vase préféré et je me suis caché sous la table.","Aujourd’hui, en repensant à cette scène, je sais que la peur de décevoir est pire que la punition."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche le verbe à l’imparfait qui dit l’habitude.","aide":"Une habitude : « chaque été »…","type":"zone","document":"gm","multiple":false},{"enonce":"Touche le verbe qui dit l’événement marquant (au passé composé).","aide":"Un matin précis, un geste précis.","type":"zone","document":"gm","multiple":false},{"enonce":"Qui parle dans la dernière phrase ?","aide":"Regarde « Aujourd’hui » et « je sais que ».","type":"choix","options":[{"id":"a","texte":"La grand-mère, qui gronde l’enfant dans la cour"},{"id":"b","texte":"Un témoin extérieur, qui observe la scène de loin"},{"id":"c","texte":"L’enfant qui se cache sous la table de la cuisine"},{"id":"d","texte":"L’adulte qui écrit aujourd’hui et tire une leçon"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m3"]},"explication":"**Partions** est à l’imparfait : le temps des habitudes et du décor."},{"cle":{"type":"zone","ids":["m11"]},"explication":"Le participe **cassé** (« j’ai cassé ») dit l’événement marquant : ici, le passé composé."},{"cle":{"type":"choix","ids":["d"]},"explication":"C’est le **je qui écrit** : l’adulte, avec son regard rétrospectif, commente et tire une leçon au présent."}]$ex$::jsonb),
  ('b126ab7d-8f1f-5918-908d-c1e552dd845d'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Quel genre est-ce ?","competence":"analyser-texte","situation":"Quatre passages écrits pour l’exercice. Chacun relève d’un genre différent : à toi de les reconnaître.","documents":[{"id":"genres","type":"texte","genre":"recit","titre":"Quatre passages","blocs":["Mardi 3 mars. Aujourd’hui, le prof m’a rendu ma copie : 9 sur 20. J’ai honte, je n’en parlerai à personne.","Ministre pendant trois ans, j’ai signé des traités, reçu des rois et vu de près les coulisses du pouvoir.","Moi, Éric Dalle, auteur de ce livre, je vous raconte ici mon enfance à Brest, telle que je m’en souviens.","Le narrateur de ce roman, Julien, a une enfance proche de la mienne, mais j’ai tout réarrangé : rien ne m’engage à la vérité."],"source":"Passages écrits pour l’exercice"}],"questions":[{"enonce":"Relie chaque passage à son genre.","aide":"Regarde la date, la vie publique, le nom de l’auteur et la phrase « rien ne m’engage à la vérité ».","type":"association","gauche":[{"id":"g0","texte":"Passage 1 : « Mardi 3 mars… »"},{"id":"g1","texte":"Passage 2 : « Ministre pendant trois ans… »"},{"id":"g2","texte":"Passage 3 : « Moi, Éric Dalle… »"},{"id":"g3","texte":"Passage 4 : « Le narrateur de ce roman… »"}],"droite":[{"id":"d0","texte":"Les Mémoires"},{"id":"d1","texte":"L’autobiographie"},{"id":"d2","texte":"Le roman autobiographique"},{"id":"d3","texte":"Le journal intime"}]},{"enonce":"Dans le passage 2, touche les **trois mots** qui relèvent de la vie publique.","aide":"Un métier politique, des papiers officiels, des personnes puissantes.","type":"zone","document":"genres","multiple":true},{"enonce":"Dans le passage 4, touche le mot qui prouve que l’auteur ne respecte pas le pacte de vérité.","aide":"Le verbe dit que la vie a été modifiée.","type":"zone","document":"genres","multiple":false},{"enonce":"Pourquoi le passage 3 respecte-t-il le pacte autobiographique ?","aide":"Qui dit « je » ? Qui signe le livre ? Qui a vécu l’enfance ?","type":"choix","options":[{"id":"a","texte":"Parce qu’il est écrit au présent, comme un journal du jour"},{"id":"b","texte":"Parce qu’auteur, narrateur et personnage sont la même personne"},{"id":"c","texte":"Parce qu’il raconte une enfance, avec des souvenirs d’école"},{"id":"d","texte":"Parce qu’il décrit la ville de Brest avec beaucoup de précision"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g3":"d2","g0":"d3"}},"explication":"Le **journal** est écrit au jour le jour, les **Mémoires** racontent la vie publique, l’**autobiographie** suit le pacte, le **roman autobiographique** n’a pas de pacte."},{"cle":{"type":"zone","ids":["m23","m31","m34"]},"explication":"**Ministre, traités, rois** : les Mémoires racontent la vie publique et les grands événements traversés."},{"cle":{"type":"zone","ids":["m81"]},"explication":"**Réarrangé** : l’auteur transforme sa vie, il n’est pas tenu à la vérité."},{"cle":{"type":"choix","ids":["b"]},"explication":"**L’auteur, le narrateur et le personnage principal** coïncident : c’est le pacte de Philippe Lejeune."}]$ex$::jsonb),
  ('b126ab7d-8f1f-5918-908d-c1e552dd845d'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Pourquoi écrire son enfance ?","competence":"analyser-texte","situation":"Un vieil homme revient dans la cour de son école et écrit ces lignes. Lis-les en séparant ce qu’il était, et ce qu’il comprend maintenant.","documents":[{"id":"cour","type":"texte","genre":"recit","titre":"Retour à l’école","blocs":["Je reviens, cinquante ans plus tard, dans la cour de mon école. Le platane est toujours là.","À l’époque, j’étais un petit garçon sérieux qui ne parlait presque jamais ; je regardais les autres jouer.","Je comprends aujourd’hui que ma timidité était une façon de me protéger. J’écris ces pages pour ne pas oublier, et pour que mes petits-enfants sachent d’où ils viennent."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Dans le deuxième paragraphe, touche les **trois verbes à l’imparfait** qui décrivent l’enfant d’autrefois.","aide":"L’imparfait décrit ce qu’il était et faisait habituellement.","type":"zone","document":"cour","multiple":true},{"enonce":"Touche le verbe qui montre l’adulte qui comprend aujourd’hui ce que l’enfant ignorait.","aide":"Il est au présent et il dit « aujourd’hui ».","type":"zone","document":"cour","multiple":false},{"enonce":"Relie chaque phrase du texte au motif qu’elle exprime.","aide":"Pense à ce que cherche l’auteur : garder, donner, éclairer.","type":"association","gauche":[{"id":"g0","texte":"« pour ne pas oublier »"},{"id":"g1","texte":"« pour que mes petits-enfants sachent d’où ils viennent »"},{"id":"g2","texte":"« ma timidité était une façon de me protéger »"}],"droite":[{"id":"d0","texte":"Se comprendre"},{"id":"d1","texte":"Se souvenir"},{"id":"d2","texte":"Transmettre"}]},{"enonce":"Où voit-on le mieux le décalage entre les deux « je » ?","aide":"Le décalage, c’est ce que sait l’adulte et que l’enfant ignorait.","type":"choix","options":[{"id":"a","texte":"Dans la phrase « Le platane est toujours là »"},{"id":"b","texte":"Dans le groupe « dans la cour de mon école »"},{"id":"c","texte":"Dans la phrase « Je comprends aujourd’hui que ma timidité… »"},{"id":"d","texte":"Dans la phrase « J’étais un petit garçon sérieux »"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m21","m28","m32"]},"explication":"**Étais, parlait, regardais** : l’imparfait pose le décor et les habitudes de l’enfant."},{"cle":{"type":"zone","ids":["m37"]},"explication":"**Comprends** : le je qui écrit commente ce que le je qui a vécu ne savait pas."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g1":"d2"}},"explication":"Il écrit pour **se souvenir**, pour **transmettre** à ses petits-enfants et pour **se comprendre**."},{"cle":{"type":"choix","ids":["c"]},"explication":"Cette phrase montre l’adulte qui **explique** ce que l’enfant vivait sans le savoir : c’est le regard rétrospectif."}]$ex$::jsonb),
  ('03092d6f-1e84-5f5c-947d-46ef8127f1bc'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Une nuit de juin 1944","competence":"analyser-texte","situation":"Un ancien enfant raconte, dans un texte écrit pour l’exercice, une nuit de la Seconde Guerre mondiale. Regarde ce qui rend son récit vrai.","documents":[{"id":"caen","type":"texte","genre":"recit","titre":"La nuit des bombes","blocs":["En juin 1944, j’avais dix ans et nous habitions à Caen. Cette nuit-là, ma mère a serré contre elle la boîte où elle gardait nos photos.","Je sentais la poussière et la peur. Je n’ai jamais oublié ce silence, après la dernière explosion."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche les **deux repères réels** : une date et un lieu.","aide":"Un nombre à quatre chiffres et le nom d’une ville.","type":"zone","document":"caen","multiple":true},{"enonce":"Touche les **deux détails concrets** : un objet et une odeur.","aide":"Ce qu’on peut serrer dans les bras, et ce qu’on sent.","type":"zone","document":"caen","multiple":true},{"enonce":"Pourquoi ces détails valent-ils mieux qu’un chapitre d’histoire ?","aide":"On peut lire qu’une ville a été bombardée, ou voir une mère qui serre une boîte de photos.","type":"choix","options":[{"id":"a","texte":"Ils allongent le texte sans rien apprendre au lecteur"},{"id":"b","texte":"Ils font voir ce que cela faisait, et rendent le passé habitable"},{"id":"c","texte":"Ils remplacent toutes les dates et tous les chiffres du manuel"},{"id":"d","texte":"Ils prouvent que l’auteur exagère et invente des détails"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m2","m11"]},"explication":"**1944** et **Caen** forment l’ancrage référentiel : des repères réels qui situent le récit."},{"cle":{"type":"zone","ids":["m21","m30"]},"explication":"**Boîte** et **poussière** sont des détails concrets : ils rendent la scène visible."},{"cle":{"type":"choix","ids":["b"]},"explication":"Le détail vécu rend le passé **habitable** : le lecteur passe de « je sais » à « je vois »."}]$ex$::jsonb),
  ('03092d6f-1e84-5f5c-947d-46ef8127f1bc'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"La place de mon père","competence":"analyser-texte","situation":"Voici un texte écrit pour l’exercice, « à la manière » d’Annie Ernaux : une écriture volontairement sans effets.","documents":[{"id":"pere","type":"texte","genre":"recit","titre":"Le café-épicerie","blocs":["Mon père tenait un petit café-épicerie. Il se levait à cinq heures, servait les ouvriers, rendait la monnaie.","Quand on parlait des bourgeois, il disait : « On n’est pas de leur monde. »","Un soir, je lui ai annoncé que j’entrais à l’université. Il a hoché la tête. Il n’a rien dit."],"source":"Texte écrit pour l’exercice, à la manière d’Annie Ernaux"}],"questions":[{"enonce":"Touche les **deux mots** du premier paragraphe qui disent le milieu du père.","aide":"Ce qu’il sert, ce qu’il rend : son quotidien de commerçant.","type":"zone","document":"pere","multiple":true},{"enonce":"Quel effet produit cette écriture plate, sans effets ?","aide":"Imagine le même passage avec des exclamations et des belles images.","type":"choix","options":[{"id":"a","texte":"Elle allonge le récit en multipliant les descriptions"},{"id":"b","texte":"Elle rend le texte plus drôle et plus léger pour le lecteur"},{"id":"c","texte":"Elle ne trahit pas ce monde : elle le montre tel qu’il est"},{"id":"d","texte":"Elle cache volontairement les émotions du père au lecteur"}],"multiple":false},{"enonce":"Relie chaque œuvre à ce qu’elle raconte.","aide":"Relis les trois usages du « je » dans ton cours.","type":"association","gauche":[{"id":"g0","texte":"Primo Levi, *Si c’est un homme*"},{"id":"g1","texte":"Annie Ernaux, *La Place*"},{"id":"g2","texte":"Georges Perec, *W ou le souvenir d’enfance*"},{"id":"g3","texte":"Azouz Begag, *Le Gone du Chaâba*"}],"droite":[{"id":"d0","texte":"L’écart entre deux milieux"},{"id":"d1","texte":"Le trou de la mémoire et la disparition des parents"},{"id":"d2","texte":"L’enfance dans un bidonville lyonnais"},{"id":"d3","texte":"Le témoignage sur Auschwitz"}]},{"enonce":"À quel usage du « je » ce texte appartient-il ?","aide":"Le père, son café, les bourgeois, l’université : de quoi est-il question ?","type":"choix","options":[{"id":"a","texte":"Le récit d’exil"},{"id":"b","texte":"Le récit d’un milieu social"},{"id":"c","texte":"Le journal intime"},{"id":"d","texte":"Le témoignage sur un événement historique"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m14","m17"]},"explication":"**Ouvriers** et **monnaie** disent le monde du père : un petit commerce de quartier."},{"cle":{"type":"choix","ids":["c"]},"explication":"L’écriture plate évite de **trahir** le monde décrit : le silence du père en dit plus qu’une phrase brillante."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g3":"d2","g0":"d3"}},"explication":"Levi **témoigne**, Ernaux raconte un **milieu**, Perec le **trou de mémoire**, Begag l’**enfance d’immigré**."},{"cle":{"type":"choix","ids":["b"]},"explication":"Le texte raconte un **milieu** et l’écart avec le monde où l’école mène l’enfant."}]$ex$::jsonb),
  ('03092d6f-1e84-5f5c-947d-46ef8127f1bc'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Témoigner pour que l’on sache","competence":"analyser-document","situation":"Deux documents : un témoignage imaginé pour l’exercice et un extrait de manuel. Ils n’apprennent pas la même chose.","documents":[{"id":"temoin","type":"texte","genre":"recit","titre":"Témoignage","blocs":["Le 16 juillet 1942, à Paris, des policiers ont sonné chez nous avant l’aube. Je tenais la main de ma petite sœur ; elle serrait sa poupée de chiffon.","Vous qui lisez ces lignes, ne dites pas que vous ne saviez pas."],"source":"Témoignage imaginé pour l’exercice"},{"id":"manuel","type":"texte","genre":"article","titre":"Extrait de manuel","blocs":["Les 16 et 17 juillet 1942, la police française arrête à Paris et en banlieue plus de 12 000 Juifs, dont plus de 4 000 enfants."],"source":"Extrait rédigé pour l’exercice"}],"questions":[{"enonce":"Dans le témoignage, touche les **quatre mots** qui donnent la date et le lieu.","aide":"Un jour, un mois, une année, une ville.","type":"zone","document":"temoin","multiple":true},{"enonce":"Touche l’objet qui donne un visage à la scène.","aide":"Ce que la petite sœur serre dans ses bras.","type":"zone","document":"temoin","multiple":false},{"enonce":"Touche le mot par lequel l’auteur s’adresse directement au lecteur.","aide":"Un pronom de la deuxième personne, au début de la dernière phrase.","type":"zone","document":"temoin","multiple":false},{"enonce":"Relie chaque élément à son rôle dans le témoignage.","aide":"Un témoignage a une double valeur : documentaire et morale.","type":"association","gauche":[{"id":"g0","texte":"La date et le lieu précis"},{"id":"g1","texte":"« Vous qui lisez ces lignes… »"},{"id":"g2","texte":"La poupée de chiffon"}],"droite":[{"id":"d0","texte":"Valeur morale : lutter contre l’oubli"},{"id":"d1","texte":"Valeur documentaire : établir ce qui a eu lieu"},{"id":"d2","texte":"Un détail concret qui rend le passé visible"}]},{"enonce":"Que gagne le lecteur en lisant les deux documents ensemble ?","aide":"Que dit le manuel ? Que montre le témoignage ?","type":"choix","options":[{"id":"a","texte":"Il sait combien de personnes ont été arrêtées et voit ce que cela faisait"},{"id":"b","texte":"Il oublie tous les chiffres et ne garde qu’une émotion assez vague"},{"id":"c","texte":"Il n’apprend que la date de l’événement, sans rien d’autre à retenir"},{"id":"d","texte":"Il n’apprend rien de plus que ce que dit déjà le manuel d’histoire"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m1","m2","m3","m5"]},"explication":"**16, juillet, 1942, Paris** forment l’ancrage référentiel : des repères réels."},{"cle":{"type":"zone","ids":["m26"]},"explication":"La **poupée** est un détail concret : il fait voir ce que cela faisait."},{"cle":{"type":"zone","ids":["m29"]},"explication":"**Vous** : l’adresse au lecteur l’implique et l’oblige à ne pas oublier."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g2":"d2"}},"explication":"La date établit les faits, l’adresse lutte contre l’oubli et la poupée rend la scène visible."},{"cle":{"type":"choix","ids":["a"]},"explication":"Le manuel donne l’**échelle** (12 000 arrestations), le témoignage donne le **visage** : on passe de « je sais » à « je vois »."}]$ex$::jsonb),
  ('d46b454f-3211-546c-9998-5ecda2dac490'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Monsieur Grippe-Sou","competence":"analyser-texte","situation":"Un auteur se moque d’un avare dans un texte écrit pour l’exercice. Regarde comment il grossit le trait.","documents":[{"id":"avare","type":"texte","genre":"recit","titre":"Un avare","blocs":["Monsieur Grippe-Sou ne dormait jamais que d’un œil, l’autre étant réservé à sa cassette. Il comptait ses pièces avant le dîner, pendant le dîner, et rêvait de les recompter après.","Quand son fils toussait, il calculait le prix du sirop avant de s’inquiéter de sa santé."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche l’objet qui obsède Monsieur Grippe-Sou.","aide":"Un petit coffre où l’on range l’argent.","type":"zone","document":"avare","multiple":false},{"enonce":"Quel procédé l’auteur emploie-t-il pour peindre ce personnage ?","aide":"Peut-on vraiment dormir d’un seul œil ? Que fait l’auteur du défaut ?","type":"choix","options":[{"id":"a","texte":"Le pamphlet : un texte qui attaque violemment quelqu’un"},{"id":"b","texte":"La caricature : un défaut poussé jusqu’au ridicule"},{"id":"c","texte":"Le pastiche : l’imitation du style d’un autre écrivain"},{"id":"d","texte":"Le portrait élogieux : un éloge qui n’a aucun défaut"}],"multiple":false},{"enonce":"Relie chaque personnage au trait que la caricature grossit.","aide":"Pense aux personnages de Molière.","type":"association","gauche":[{"id":"g0","texte":"L’avare"},{"id":"g1","texte":"Le médecin"}],"droite":[{"id":"d0","texte":"Un jargon : il ne parle plus qu’en latin"},{"id":"d1","texte":"Une obsession : sa cassette"}]}]}$ex$::jsonb,
