  ('d46b454f-3211-546c-9998-5ecda2dac490'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Quatre manières de se moquer","competence":"analyser-texte","situation":"Trois courts extraits écrits pour l’exercice : chacun se moque à sa façon. Repère les procédés.","documents":[{"id":"extraits","type":"texte","genre":"recit","titre":"Trois extraits","blocs":["Sur le champ d’honneur de la cantine, les armées de haricots avancèrent sous le regard des dieux.","Achille, le héros divin, se gratta le nez : « Zut alors, mon pote, tu m’as tordu ma lance ! »","« Ô désespoir ! Ô cartable ennemi ! N’ai-je donc tant lu que pour cet examen ? » s’écria le collégien."],"source":"Extraits écrits pour l’exercice"}],"questions":[{"enonce":"Relie chaque extrait à son procédé.","aide":"Regarde le sujet (noble ou bas) et le style (noble ou familier).","type":"association","gauche":[{"id":"g0","texte":"Extrait 1 : la bataille des haricots"},{"id":"g1","texte":"Extrait 2 : Achille et son « pote »"},{"id":"g2","texte":"Extrait 3 : « Ô désespoir ! Ô cartable ennemi ! »"}],"droite":[{"id":"d0","texte":"Le burlesque : héros qui parlent comme des valets"},{"id":"d1","texte":"La parodie : imitation d’une tirade tragique pour s’en moquer"},{"id":"d2","texte":"L’héroï-comique : sujet bas, style noble"}]},{"enonce":"Dans l’extrait 1, touche le mot au style noble qui tranche avec la cantine.","aide":"Un mot qu’on emploierait pour un soldat courageux.","type":"zone","document":"extraits","multiple":false,"portee":[0]},{"enonce":"Dans l’extrait 2, touche les **deux mots familiers** qui détonnent avec un héros divin.","aide":"Des mots qu’on dit à un camarade, pas à un roi.","type":"zone","document":"extraits","multiple":true,"portee":[1]},{"enonce":"Quelle différence entre pastiche et parodie illustre l’extrait 3 ?","aide":"Que fait l’auteur du cartable et de l’examen, face à un style tragique ?","type":"choix","options":[{"id":"a","texte":"Il attaque le collégien sans rire : c’est une satire"},{"id":"b","texte":"Il n’imite rien : c’est un pamphlet"},{"id":"c","texte":"Il imite le ton d’une tirade tragique pour s’en moquer : c’est une parodie"},{"id":"d","texte":"Il imite le ton d’une tirade sans se moquer : c’est un pastiche"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"Extrait 1 : sujet **bas** (une cantine) dans un style **noble**. Extrait 2 : héros **nobles** au style **familier**. Extrait 3 : on **imite** un style tragique **pour s’en moquer**."},{"cle":{"type":"zone","ids":["m4"]},"explication":"Le mot **honneur** appartient au style noble : il contraste avec la cantine, c’est l’effet héroï-comique."},{"cle":{"type":"zone","ids":["m26","m29"]},"explication":"**Zut** et **pote** sont familiers : le héros parle comme un valet, c’est le burlesque."},{"cle":{"type":"choix","ids":["c"]},"explication":"Un **pastiche** imite ; une **parodie** imite pour **se moquer** : ici le collégien prend le ton tragique pour un simple examen."}]$ex$::jsonb),
  ('d46b454f-3211-546c-9998-5ecda2dac490'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"L’île de Mirabol","competence":"analyser-texte","situation":"Un conte écrit pour l’exercice, dans l’esprit de Voltaire. Le narrateur a l’air de tout approuver. Mais est-ce bien ce qu’il pense ?","documents":[{"id":"mirabol","type":"texte","genre":"recit","titre":"Dans l’île de Mirabol","blocs":["Dans l’île de Mirabol, tout était pour le mieux. On pendait les voleurs de pain avec beaucoup de courtoisie, et les juges, fort distingués, dormaient pendant les procès par respect pour le silence.","On s’extasiait mille fois par jour sur la beauté du gouvernement. Le seul habitant un peu triste était un ouvrier qui n’avait rien mangé depuis trois jours, mais c’était un caractère chagrin."],"source":"Texte écrit pour l’exercice, dans l’esprit de Voltaire"}],"questions":[{"enonce":"Touche les **deux mots** qui louent ce que l’auteur condamne.","aide":"Cherche deux compliments appliqués à la justice.","type":"zone","document":"mirabol","multiple":true},{"enonce":"Que pense réellement le narrateur de la justice de Mirabol ?","aide":"On pend des voleurs de pain, et les juges dorment.","type":"choix","options":[{"id":"a","texte":"Qu’elle est lente mais nécessaire"},{"id":"b","texte":"Qu’elle est admirable"},{"id":"c","texte":"Qu’elle est cruelle et absurde"},{"id":"d","texte":"Qu’elle est sans importance"}],"multiple":false},{"enonce":"Relie chaque passage à sa figure.","aide":"Approuver faussement, grossir, feindre de ne pas comprendre.","type":"association","gauche":[{"id":"g0","texte":"« tout était pour le mieux »"},{"id":"g1","texte":"« mille fois par jour »"},{"id":"g2","texte":"« c’était un caractère chagrin »"}],"droite":[{"id":"d0","texte":"Hyperbole : elle grossit"},{"id":"d1","texte":"Antiphrase : il feint d’approuver"},{"id":"d2","texte":"Fausse naïveté : il feint de ne pas comprendre"}]},{"enonce":"Complète la règle.","aide":"Le lecteur doit comprendre ce que le texte ne dit pas.","type":"trous","segments":["L’ironie demande une ",0," avec le lecteur, qui rétablit seul le vrai ",1,"."],"banque":["complicité","rime","sens","titre"]}]}$ex$::jsonb,
