  ('6137ca1f-0984-5d8a-a24f-c1cce16bb119'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le Lion et la rivière","competence":"analyser-texte","situation":"Une fable écrite pour l’exercice. Un Lion, un Lièvre, et une question sur le pouvoir.","documents":[{"id":"fable","type":"texte","genre":"recit","titre":"Le Lion et le Lièvre","blocs":["Le Lion, roi des forêts, fit proclamer que la rivière lui appartenait. Un Lièvre, qui avait soif, vint s’y désaltérer.","« Je suis le plus fort, dit le Lion : la rivière est à moi. — Et la pluie, Sire ? demanda le Lièvre. » Le Lion n’eut pas de réponse, mais il eut le Lièvre."],"source":"Fable écrite pour l’exercice"}],"questions":[{"enonce":"Touche les **deux mots** par lesquels le Lion justifie son abus.","aide":"C’est sa seule raison : la force.","type":"zone","document":"fable","multiple":true},{"enonce":"Pourquoi l’auteur parle-t-il d’un lion plutôt que d’un roi ?","aide":"Que risque un auteur qui critique un roi ouvertement ?","type":"choix","options":[{"id":"a","texte":"Parce que le détour par l’animal protège : on nomme sans nommer"},{"id":"b","texte":"Parce qu’il n’aime pas les rois"},{"id":"c","texte":"Parce que la fable est un genre inventé au XXe siècle"},{"id":"d","texte":"Parce que les lions parlent mieux"}],"multiple":false},{"enonce":"Relie chaque cible de la satire à son exemple.","aide":"Relis le tableau « Cibles et enjeux » de ton cours.","type":"association","gauche":[{"id":"g0","texte":"Les abus de pouvoir"},{"id":"g1","texte":"L’hypocrisie religieuse"},{"id":"g2","texte":"La vanité des grands"}],"droite":[{"id":"d0","texte":"*Tartuffe* de Molière"},{"id":"d1","texte":"Portraits et caricatures"},{"id":"d2","texte":"La Fontaine : « La raison du plus fort est toujours la meilleure »"}]}]}$ex$::jsonb,
