  ('6137ca1f-0984-5d8a-a24f-c1cce16bb119'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Un Persan à Paris","competence":"analyser-texte","situation":"Une lettre écrite pour l’exercice, à la manière des *Lettres persanes* : un étranger raconte les usages d’un pays qu’il découvre.","documents":[{"id":"persan","type":"texte","genre":"lettre","titre":"Lettre de Zeïd","blocs":["Ce peuple est étrange. Chaque matin, un homme s’enferme trois heures avec son valet pour que celui-ci lui fabrique des cheveux d’une autre couleur que les siens ; puis il sort se promener pour montrer que ces cheveux sont à lui.","Les femmes dépensent le revenu d’un village en rubans, et tout le monde appelle cela de la raison. Je demeure stupéfait."],"source":"Lettre écrite pour l’exercice, à la manière des Lettres persanes de Montesquieu"}],"questions":[{"enonce":"Touche les **deux mots** qui montrent l’étonnement du voyageur.","aide":"Un adjectif au début, un adjectif à la fin.","type":"zone","document":"persan","multiple":true},{"enonce":"Touche le mot qui grossit la dépense des femmes.","aide":"La dépense est comparée à une communauté entière.","type":"zone","document":"persan","multiple":false},{"enonce":"Que pense réellement l’auteur de ces usages ?","aide":"Zeïd dit « de la raison » : le pense-t-il vraiment ?","type":"choix","options":[{"id":"a","texte":"Qu’ils sont admirables"},{"id":"b","texte":"Qu’ils sont trop chers pour lui"},{"id":"c","texte":"Qu’ils sont raisonnables"},{"id":"d","texte":"Qu’ils sont absurdes et vaniteux"}],"multiple":false},{"enonce":"Complète la phrase.","aide":"C’est le ressort de la satire : le regard du Persan.","type":"trous","segments":["Le regard ",0," rend ",1," ce que l’habitude a rendu ",2,"."],"banque":["étrange","étranger","comique","rare","normal"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m3","m63"]},"explication":"**Étrange** et **stupéfait** disent son étonnement : il trouve absurde ce que l’habitude a rendu normal."},{"cle":{"type":"zone","ids":["m49"]},"explication":"**Village** : c’est une hyperbole, qui grossit l’usage jusqu’à l’absurde."},{"cle":{"type":"choix","ids":["d"]},"explication":"Le narrateur dit « raison » pour dire **absurdité** : c’est l’ironie, qui feint d’approuver."},{"cle":{"type":"trous","trous":[["etranger"],["etrange","absurde"],["normal","familier"]]},"affichage":"étranger · étrange · normal","explication":"Le regard **étranger** rend **étrange** ce que l’habitude a rendu **normal**."}]$ex$::jsonb),
  ('6137ca1f-0984-5d8a-a24f-c1cce16bb119'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Jusqu’où peut-on rire ?","competence":"analyser-document","situation":"Un sketch écrit pour l’exercice, et un échange de messages entre deux élèves qui jugent deux dessins de presse. Tu vas juger la satire.","documents":[{"id":"sketch","type":"texte","genre":"article","titre":"Le ministre inaugure","blocs":["Le ministre inaugure un pont, un rond-point, une fontaine, une plaque, puis sa propre statue. Il fit preuve, comme toujours, d’une grande modestie.","Le peuple applaudit. Il applaudissait déjà avant de savoir pourquoi."],"source":"Sketch écrit pour l’exercice"},{"id":"sms","type":"dialogue","modele":"sms","participants":[{"nom":"Lina","emoji":"👧","cote":"gauche"},{"nom":"Yanis","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Lina","texte":"Le dessin A se moque d’un maire qui détourne l’argent de la ville. Je le trouve bon !"},{"qui":"Yanis","texte":"Le dessin B montre des chômeurs paresseux sur un canapé. Ça fait rire, mais c’est injuste."}]}],"questions":[{"enonce":"Touche l’objet qui trahit la vanité du ministre.","aide":"Il inaugure tout, y compris quelque chose à son image.","type":"zone","document":"sketch","multiple":false},{"enonce":"Que produit l’énumération « un pont, un rond-point, une fontaine, une plaque, puis sa propre statue » ?","aide":"Que devient la statue du ministre, à la fin de la liste ?","type":"choix","options":[{"id":"a","texte":"Elle met sur le même plan l’utile et le vaniteux"},{"id":"b","texte":"Elle donne une information précise sur la ville"},{"id":"c","texte":"Elle raconte un dialogue"},{"id":"d","texte":"Elle adoucit la critique"}],"multiple":false},{"enonce":"Relie chaque passage à son procédé.","aide":"Liste de détails, éloge ironique, phrase finale courte.","type":"association","gauche":[{"id":"g0","texte":"« un pont, un rond-point, une fontaine, une plaque… »"},{"id":"g1","texte":"« comme toujours, d’une grande modestie »"},{"id":"g2","texte":"« Il applaudissait déjà avant de savoir pourquoi. »"}],"droite":[{"id":"d0","texte":"Antiphrase : il feint d’approuver"},{"id":"d1","texte":"Chute brève : elle referme sur un constat sans appel"},{"id":"d2","texte":"Accumulation : elle écrase la cible sous les détails"}]},{"enonce":"Touche le mot du message de Yanis qui renforce un préjugé.","aide":"Un adjectif qui juge des personnes sans travail.","type":"zone","document":"sms","multiple":false},{"enonce":"Quel dessin réussit sa satire ?","aide":"Une satire réussie vise-t-elle les puissants ou ceux qui souffrent déjà ?","type":"choix","options":[{"id":"a","texte":"Le dessin B, qui se moque de ceux qui subissent déjà"},{"id":"b","texte":"Les deux, car on peut rire de tout"},{"id":"c","texte":"Aucun, car la satire est interdite"},{"id":"d","texte":"Le dessin A, qui fait rire de ce qui mérite d’être combattu"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m14"]},"explication":"La **statue** montre la vanité : le ministre inaugure sa propre image."},{"cle":{"type":"choix","ids":["a"]},"explication":"L’**énumération** met sur le même plan des choses incomparables : la statue vaniteuse devient aussi « normale » qu’un pont."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"L’**accumulation** écrase, l’**antiphrase** feint d’approuver, la **chute brève** referme sur un constat sans appel."},{"cle":{"type":"zone","ids":["m25"]},"explication":"**Paresseux** renforce un préjugé : le rire manque sa cible."},{"cle":{"type":"choix","ids":["d"]},"explication":"Le dessin **A** vise un abus de pouvoir. Le dessin **B** renforce un **préjugé** : le rire y manque sa cible."}]$ex$::jsonb)
) AS v (chapter_id, position, etoiles, gemmes, xp, nb_questions, contenu, cles);

INSERT INTO public.exercices (id, chapter_id, position, etoiles, gemmes, xp, nb_questions, contenu)
SELECT s.id, s.chapter_id, s.position, s.etoiles, s.gemmes, s.xp, s.nb_questions, s.contenu
FROM exercices_seed s
JOIN public.chapters c ON c.id = s.chapter_id
ON CONFLICT (id) DO UPDATE
  SET etoiles      = EXCLUDED.etoiles,
      nb_questions = EXCLUDED.nb_questions,
      contenu      = EXCLUDED.contenu,
      updated_at   = now();

INSERT INTO public.exercices_cles (exercice_id, cles)
SELECT s.id, s.cles
FROM exercices_seed s
JOIN public.exercices e ON e.id = s.id
ON CONFLICT (exercice_id) DO UPDATE SET cles = EXCLUDED.cles;

-- Contrôle : combien d'exercices de ce fichier sont en base, et combien sautés.
DO $$
DECLARE
  v_attendus INTEGER;
  v_poses    INTEGER;
BEGIN
  SELECT count(*) INTO v_attendus FROM exercices_seed;
  SELECT count(*) INTO v_poses FROM public.exercices e JOIN exercices_seed s ON s.id = e.id;
  RAISE NOTICE 'Cahier 3e (1) : % exercices posés sur % (les autres n''ont pas leur chapitre en base).', v_poses, v_attendus;
  DROP TABLE IF EXISTS pg_temp.exercices_seed;
END $$;
